package com.ticksync.music;

/**
 *  * Audio pipeline for game-music mode.
 * * <p>v1.0 supports MIDI only. OGG modes will be added in a future release.
 */
public enum AudioMode {
    MIDI
}

package com.ticksync.music;

import javax.sound.midi.InvalidMidiDataException;
import javax.sound.midi.MidiChannel;
import javax.sound.midi.MidiMessage;
import javax.sound.midi.MidiUnavailableException;
import javax.sound.midi.Receiver;
import javax.sound.midi.ShortMessage;
import javax.sound.midi.Synthesizer;
import lombok.extern.slf4j.Slf4j;

/**
 * Fixes OSRS's non-standard bank selection so Java's synthesizer picks the
 * correct instrument patches from the OSRS soundfont.
 *
 * The problem:
 *   Standard MIDI selects instrument banks with CC0 (Bank MSB).
 *   Java's Synthesizer uses CC0 to pick a bank from the soundfont.
 *   OSRS MIDI files select banks with CC32 (Bank LSB) instead — non-standard.
 *   Result: Java reads CC32 as a harmless LSB byte and ignores it, then uses
 *   CC0=0 (always), landing on the wrong instruments.
 *
 * The fix (same approach used by music-mask by lequietriot):
 *   Sit between the Sequencer and Synthesizer as a Receiver.
 *   When we see CC32 (LSB), re-send it as CC0 (MSB) so the synthesizer
 *   looks in the right bank.
 *   When we see CC0 (MSB), suppress it — OSRS files send CC0=0 as a no-op
 *   before CC32, and letting it through would reset the bank we just set.
 *   Everything else passes through unchanged.
 */
@Slf4j
public final class BankFixReceiver implements Receiver {
    private static final int CONTROL_CHANGE = ShortMessage.CONTROL_CHANGE;
    private static final int PROGRAM_CHANGE = ShortMessage.PROGRAM_CHANGE;
    private static final int CC_BANK_MSB = 0; // CC0  — standard bank select
    private static final int CC_BANK_LSB = 32; // CC32 — OSRS bank select

    /** MIDI channel index that Java Sound hardcodes as percussion (GM channel 10). */
    private static final int GM_DRUM_CHANNEL = 9;

    private final Receiver delegate;
    private final Synthesizer synthesizer;

    /** Track pending bank MSB per channel so we can pass it to programChange(bank, prog). */
    private final int[] pendingBankMSB = new int[16];

    /**
     * @param synthesizer The synthesizer whose default Receiver we wrap.
     */
    public BankFixReceiver(Synthesizer synthesizer) throws MidiUnavailableException {
        this.delegate = synthesizer.getReceiver();
        this.synthesizer = synthesizer;
        log.info("BankFixReceiver wired in — CC32 bank selects will be remapped to CC0, ch9 drum lock bypassed");
    }

    @Override
    public void send(MidiMessage message, long timeStamp) {
        if (message instanceof ShortMessage) {
            ShortMessage sm = (ShortMessage) message;
            int ch = sm.getChannel();
            int cmd = sm.getCommand();
            int d1 = sm.getData1();
            int d2 = sm.getData2();

            if (cmd == CONTROL_CHANGE) {
                // CC32 (OSRS bank LSB) → re-send as CC0 (Bank MSB) so Java
                // synthesizer selects the correct soundfont bank.
                if (d1 == CC_BANK_LSB) {
                    log.trace("BankFixReceiver intercepted CC32 on ch{} value={} → re-sending as CC0", ch, d2);
                    pendingBankMSB[ch] = d2;
                    try {
                        ShortMessage fixed = new ShortMessage(CONTROL_CHANGE, ch, CC_BANK_MSB, d2);
                        delegate.send(fixed, timeStamp);
                    } catch (InvalidMidiDataException e) {
                        log.debug(
                                "BankFixReceiver: failed to construct CC0 message for ch{} value={}: {}",
                                ch,
                                d2,
                                e.getMessage());
                        delegate.send(message, timeStamp);
                    }
                    return;
                }

                // CC0 (Bank MSB) — OSRS files send this as 0 before every CC32.
                // Suppress it so it doesn't clobber the bank we're about to set.
                if (d1 == CC_BANK_MSB) {
                    return;
                }
            } else if (cmd == PROGRAM_CHANGE && ch == GM_DRUM_CHANNEL) {
                // Java's Gervill synthesizer locks channel index 9 as percussion.
                // Bypass the delegate receiver and call the MidiChannel API directly —
                // this is the only way to override the drum-channel lock in Gervill.
                MidiChannel[] channels = synthesizer.getChannels();
                if (channels != null && channels[ch] != null) {
                    int bank = pendingBankMSB[ch];
                    log.trace(
                            "BankFixReceiver: ch9 program change {} bank {} via direct MidiChannel API (bypassing drum lock)",
                            d1,
                            bank);
                    channels[ch].programChange(bank, d1);
                }
                return; // Don't send through delegate — Gervill would ignore it on ch9
            }
        }

        // Everything else (notes, pitch bend, other CCs, program changes on ch0-8,10-15)
        // passes through unchanged.
        delegate.send(message, timeStamp);
    }

    @Override
    public void close() {
        delegate.close();
    }
}

package com.ticksync.music;

import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.StringJoiner;
import javax.sound.midi.MidiSystem;
import javax.sound.midi.Sequence;
import lombok.extern.slf4j.Slf4j;
import net.runelite.cache.definitions.TrackDefinition;
import net.runelite.cache.definitions.loaders.TrackLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.Container;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Store;

/**
 * Loads MIDI sequences directly from the user's local OSRS cache using
 * RuneLite's cache library.
 *
 * Cache auto-detection order (first valid directory wins):
 *   1. User-configured override path (plugin config)
 *   2. ~/.runelite/jagexcache/oldschool/LIVE  (RuneLite + Jagex Launcher, 2024+)
 *   3. ~/jagexcache/oldschool/LIVE            (legacy standalone client)
 *
 * A directory is considered valid only if it exists AND contains
 * {@code main_file_cache.dat2}.
 *
 * Index 6 (IndexType.MUSIC_TRACKS) holds individual music track archives.
 * Each archive's raw data is OSRS's proprietary packed-MIDI format; RuneLite's
 * {@link TrackLoader} decodes it into standard MIDI bytes.
 *
 * The Store is opened once at plugin startup and closed on shutdown —
 * not re-opened per track.
 */
@Slf4j
public class CacheMidiLoader {
    /** Index 6 = OSRS music tracks (IndexType.MUSIC_TRACKS). */
    private static final int MUSIC_INDEX_ID = 6;

    /** Sentinel file whose presence confirms this is a real OSRS cache directory. */
    private static final String DAT2_FILENAME = "main_file_cache.dat2";

    // Opened once at init(), closed at shutdown()
    private Store store;
    private Index musicIndex;
    private boolean ready = false;
    private String resolvedCachePath;

    // ── Lifecycle ────────────────────────────────────────────────────────────

    /**
     * Locate and open the OSRS cache.
     *
     * @param configOverridePath user-configured cache path, or empty/null for auto-detection
     */
    public void init(String configOverridePath) {
        ready = false;

        File cacheDir = findCacheDir(configOverridePath);
        if (cacheDir == null) {
            // findCacheDir already logged the "not found" message
            return;
        }

        resolvedCachePath = cacheDir.getAbsolutePath();

        try {
            store = new Store(cacheDir);
            store.load();

            musicIndex = store.findIndex(MUSIC_INDEX_ID);
            if (musicIndex == null) {
                log.error(
                        "CacheMidiLoader: music index ({}) not found in cache at {}. Music will not play.",
                        MUSIC_INDEX_ID,
                        resolvedCachePath);
                closeStore();
                return;
            }

            ready = true;
            log.info(
                    "CacheMidiLoader: cache opened — music index has {} archives",
                    musicIndex.getArchives().size());
        } catch (IOException e) {
            log.error("CacheMidiLoader: failed to open cache at {}: {}", resolvedCachePath, e.getMessage());
            closeStore();
        }
    }

    /**
     * Try each candidate path in priority order and return the first valid cache directory.
     * A directory is valid if it exists and contains {@value #DAT2_FILENAME}.
     *
     * @param configOverride user-supplied override path (may be null/empty)
     * @return the first valid cache directory, or null if none found
     */
    private File findCacheDir(String configOverride) {
        String home = System.getProperty("user.home");

        // Build candidate list — File(parent, child) with "/" handles OS separators automatically
        List<File> candidates = new ArrayList<>();

        if (configOverride != null && !configOverride.trim().isEmpty()) {
            candidates.add(new File(configOverride.trim()));
        }

        // Priority 1: RuneLite + Jagex Launcher (most users in 2024+)
        candidates.add(new File(home, ".runelite/jagexcache/oldschool/LIVE"));

        // Priority 2: legacy standalone client
        candidates.add(new File(home, "jagexcache/oldschool/LIVE"));

        for (File candidate : candidates) {
            if (isValidCacheDir(candidate)) {
                log.info("CacheMidiLoader: found OSRS cache at {}", candidate.getAbsolutePath());
                return candidate;
            }
        }

        // None found — build a helpful message listing all tried paths
        StringJoiner tried = new StringJoiner(", ");
        for (File candidate : candidates) {
            tried.add(candidate.getAbsolutePath());
        }
        log.error("CacheMidiLoader: OSRS cache not found. Tried: {}. Set path manually in plugin config.", tried);
        return null;
    }

    /**
     * A cache directory is valid if it is an existing directory that contains
     * {@code main_file_cache.dat2}.
     */
    private boolean isValidCacheDir(File dir) {
        return dir.exists() && dir.isDirectory() && new File(dir, DAT2_FILENAME).exists();
    }

    /**
     * Close the cache store. Call once at plugin shutdown.
     */
    public void shutdown() {
        closeStore();
        ready = false;
        log.info("TickSync: CacheMidiLoader shut down");
    }

    // ── Track Loading ────────────────────────────────────────────────────────

    /**
     * Load a music track from the OSRS cache by its archive ID (cache ID).
     *
     * The raw archive data is decompressed via {@link Container#decompress},
     * then decoded from OSRS packed-MIDI to standard MIDI by {@link TrackLoader}.
     * The returned Sequence can be passed directly to TempoQuantizer and MidiTickPlayer.
     *
     * @param cacheId  the archive ID in index 6 (e.g. 556 for "Welcome to the Theatre")
     * @return a ready-to-quantize Sequence, or null if the track cannot be loaded
     */
    public Sequence loadTrack(int cacheId) {
        if (!ready) {
            log.warn("TickSync: CacheMidiLoader not ready — cannot load track {}", cacheId);
            return null;
        }

        try {
            // 1. Locate the archive in the music index
            Archive archive = musicIndex.getArchive(cacheId);
            if (archive == null) {
                log.warn("TickSync: no archive {} in music index (track not in this cache version?)", cacheId);
                return null;
            }

            // 2. Read raw (compressed) bytes from disk
            byte[] rawData = store.getStorage().loadArchive(archive);
            if (rawData == null || rawData.length == 0) {
                log.warn("TickSync: empty raw data for archive {}", cacheId);
                return null;
            }

            // 3. Decompress — music tracks are not XTEA-encrypted, so keys = null
            Container container = Container.decompress(rawData, null);
            byte[] decompressedData = container.data;

            // 4. Decode OSRS packed-MIDI → standard MIDI bytes
            TrackLoader loader = new TrackLoader();
            TrackDefinition def = loader.load(decompressedData);

            if (def.getMidi() == null) {
                log.warn("TickSync: TrackLoader returned null midi for archive {}", cacheId);
                return null;
            }

            // 5. Parse standard MIDI bytes into a javax.sound.midi.Sequence
            return MidiSystem.getSequence(new ByteArrayInputStream(def.getMidi()));
        } catch (Exception e) {
            log.error("TickSync: failed to load track {} from cache: {}", cacheId, e.getMessage(), e);
            return null;
        }
    }

    // ── Accessors ────────────────────────────────────────────────────────────

    /**
     * @return true if the cache was successfully opened and the music index was found
     */
    public boolean isReady() {
        return ready;
    }

    /**
     * @return the resolved cache path (for logging/debugging)
     */
    public String getCachePath() {
        return resolvedCachePath != null ? resolvedCachePath : "(not set)";
    }

    // ── Helpers ──────────────────────────────────────────────────────────────

    private void closeStore() {
        if (store != null) {
            try {
                store.close();
            } catch (IOException e) {
                log.warn("TickSync: error closing cache store: {}", e.getMessage());
            }
            store = null;
        }
        musicIndex = null;
    }
}

package com.ticksync.music;

import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Random;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Manages a list of .mid files from a user-provided folder and implements
 * track-selection logic for the three play modes.
 *
 * Thread-safety: all public methods are called from the game-tick (client) thread.
 */
@Slf4j
public class CustomMidiPlayer {
    /** Minimum pool size for shuffle — below this, shuffle degenerates to repeat. */
    private static final int MIN_SHUFFLE_POOL = 2;

    private List<File> tracks = new ArrayList<>();

    @Getter
    private int currentIndex = 0;

    /** Last index returned for SHUFFLE — prevents playing the same track twice in a row. */
    private int lastShuffleIndex = -1;

    private final Random random = new Random();

    // ── Accessors ────────────────────────────────────────────────────────────

    /**
     * Seek directly to a track by index (used by the sidebar track list).
     *
     * @return the File at that index, or null if the index is out of bounds
     */
    public File seekToIndex(int index) {
        if (index < 0 || index >= tracks.size()) {
            return null;
        }
        currentIndex = index;
        lastShuffleIndex = index;
        return tracks.get(currentIndex);
    }

    /**
     * Scan {@code folderPath} for *.mid files and store them sorted alphabetically.
     *
     * @return number of tracks found (0 if folder missing, empty, or path blank)
     */
    public int loadFolder(String folderPath) {
        tracks.clear();
        currentIndex = 0;
        lastShuffleIndex = -1;

        if (folderPath == null || folderPath.trim().isEmpty()) {
            log.warn("CustomMidiPlayer: no folder path configured");
            return 0;
        }

        File folder = new File(folderPath.trim());
        if (!folder.exists() || !folder.isDirectory()) {
            log.warn("CustomMidiPlayer: folder does not exist or is not a directory: {}", folderPath);
            return 0;
        }

        File[] files =
                folder.listFiles((dir, name) -> name.toLowerCase(Locale.ROOT).endsWith(".mid"));
        if (files == null || files.length == 0) {
            log.warn("CustomMidiPlayer: no .mid files found in {}", folderPath);
            return 0;
        }

        List<File> found = new ArrayList<>(Arrays.asList(files));
        Collections.sort(found, (a, b) -> a.getName().compareToIgnoreCase(b.getName()));
        tracks = found;

        log.info("CustomMidiPlayer: loaded {} tracks from {}", tracks.size(), folderPath);
        return tracks.size();
    }

    // ── Track selection ──────────────────────────────────────────────────────

    /**
     * Select and return the first track to play when starting a fresh session.
     * For SHUFFLE: picks a random starting index.
     * For SEQUENTIAL / REPEAT_ONE: starts at index 0.
     *
     * @return the selected File, or null if no tracks are loaded
     */
    public File getFirstTrack(CustomPlayMode mode) {
        if (tracks.isEmpty()) {
            return null;
        }

        if (mode == CustomPlayMode.SHUFFLE) {
            currentIndex = tracks.size() >= MIN_SHUFFLE_POOL ? random.nextInt(tracks.size()) : 0;
            lastShuffleIndex = currentIndex;
        } else {
            currentIndex = 0;
        }

        log.debug(
                "CustomMidiPlayer: first track [{}] {}",
                currentIndex,
                tracks.get(currentIndex).getName());
        return tracks.get(currentIndex);
    }

    /**
     * Advance to and return the next track based on the play mode.
     *
     * <ul>
     *   <li>SEQUENTIAL — increment index, wrap to 0 at end</li>
     *   <li>SHUFFLE    — random index, never the same as the last</li>
     *   <li>REPEAT_ONE — stay on the current index</li>
     * </ul>
     *
     * @return the next File, or null if no tracks are loaded
     */
    public File getNextTrack(CustomPlayMode mode) {
        if (tracks.isEmpty()) {
            return null;
        }

        switch (mode) {
            case SEQUENTIAL:
                currentIndex = (currentIndex + 1) % tracks.size();
                break;

            case SHUFFLE:
                if (tracks.size() < MIN_SHUFFLE_POOL) {
                    currentIndex = 0;
                } else {
                    int next;
                    int attempts = 0;
                    do {
                        next = random.nextInt(tracks.size());
                        attempts++;
                    } while (next == lastShuffleIndex && attempts < 10);
                    lastShuffleIndex = next;
                    currentIndex = next;
                }
                break;

            case REPEAT_ONE:
                // stay on same index
                break;
        }

        log.debug(
                "CustomMidiPlayer: next track [{}] {}",
                currentIndex,
                tracks.get(currentIndex).getName());
        return tracks.get(currentIndex);
    }

    /**
     * Step back to and return the previous track based on the play mode.
     *
     * <ul>
     *   <li>SEQUENTIAL — decrement index, wrap to end</li>
     *   <li>SHUFFLE    — random index, never the same as the last</li>
     *   <li>REPEAT_ONE — stay on the current index</li>
     * </ul>
     *
     * @return the previous File, or null if no tracks are loaded
     */
    public File getPrevTrack(CustomPlayMode mode) {
        if (tracks.isEmpty()) {
            return null;
        }

        switch (mode) {
            case SEQUENTIAL:
                currentIndex = (currentIndex - 1 + tracks.size()) % tracks.size();
                break;

            case SHUFFLE:
                if (tracks.size() < MIN_SHUFFLE_POOL) {
                    currentIndex = 0;
                } else {
                    int prev;
                    int attempts = 0;
                    do {
                        prev = random.nextInt(tracks.size());
                        attempts++;
                    } while (prev == lastShuffleIndex && attempts < 10);
                    lastShuffleIndex = prev;
                    currentIndex = prev;
                }
                break;

            case REPEAT_ONE:
                // stay on same index
                break;
        }

        log.debug(
                "CustomMidiPlayer: prev track [{}] {}",
                currentIndex,
                tracks.get(currentIndex).getName());
        return tracks.get(currentIndex);
    }

    /** @return the currently selected File, or null if no tracks loaded */
    public File getCurrentTrack() {
        return tracks.isEmpty() ? null : tracks.get(currentIndex);
    }

    /** @return filename without extension, or empty string if nothing loaded */
    public String getCurrentTrackName() {
        File f = getCurrentTrack();
        if (f == null) {
            return "";
        }
        String name = f.getName();
        int dot = name.lastIndexOf('.');
        return dot > 0 ? name.substring(0, dot) : name;
    }

    public boolean hasTracks() {
        return !tracks.isEmpty();
    }

    public int getTrackCount() {
        return tracks.size();
    }
}

package com.ticksync.music;

/**
 * Controls how tracks are selected from the custom MIDI folder.
 */
public enum CustomPlayMode {
    SEQUENTIAL("Sequential"),
    SHUFFLE("Shuffle"),
    REPEAT_ONE("Repeat one");

    private final String name;

    CustomPlayMode(String name) {
        this.name = name;
    }

    @Override
    public String toString() {
        return name;
    }
}

package com.ticksync.music;

import java.io.File;
import java.io.FileInputStream;
import java.io.InputStream;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import javax.sound.midi.MidiChannel;
import javax.sound.midi.MidiSystem;
import javax.sound.midi.Sequence;
import javax.sound.midi.Sequencer;
import javax.sound.midi.Soundbank;
import javax.sound.midi.Synthesizer;
import javax.sound.midi.Transmitter;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Manages the javax.sound.midi Synthesizer and Sequencer.
 *
 * Responsibilities:
 * - Loads the OSRS soundfont once at init
 * - Plays a tempo-quantized MIDI Sequence
 * - Starts playback aligned to a GameTick boundary
 * - Periodic drift correction to keep beats on ticks
 */
@Slf4j
public class MidiTickPlayer {
    // ── Named constants ───────────────────────────────────────────────────────

    /**
     * Duration of a single OSRS game tick in microseconds (600 ms × 1000 µs/ms).
     * All drift-correction arithmetic uses this value.
     */
    private static final long TICK_DURATION_MICROS = 600_000L;

    /**
     * Number of ticks after a track starts during which aggressive drift correction
     * is active.  25 ticks × 600 ms = 15 seconds — covers the critical lock-in window
     * where Java Sound's sequencer is most likely to wander from zero.
     */
    private static final int AGGRESSIVE_TICKS = 25;

    /**
     * Drift-correction interval during the aggressive phase.
     * 2 ticks ≈ 1.2 seconds — re-syncs quickly after track start.
     */
    private static final int AGGRESSIVE_INTERVAL = 2;

    /**
     * Drift-correction interval after the aggressive phase.
     * 8 ticks ≈ 4.8 seconds — light maintenance once the sequencer has settled.
     */
    private static final int NORMAL_INTERVAL = 8;

    /**
     * Maximum tolerated drift in microseconds before a hard re-sync is applied.
     * 20 000 µs = 20 ms — tight enough to keep beats on-tick without causing
     * audible glitches from overly frequent corrections.
     */
    private static final long DRIFT_THRESHOLD_MICROS = 20_000L;

    // ── State ─────────────────────────────────────────────────────────────────

    private volatile Synthesizer synthesizer;
    private volatile Sequencer sequencer;
    private volatile Transmitter activeTransmitter;
    private boolean pendingStart = false;

    private boolean paused = false;

    /** Delay (ms) between a game tick and sequencer.start() for ping compensation. */
    @Getter
    private int beatOffsetMs = 0;

    /** Executor for the delayed-start timer when beatOffsetMs > 0. */
    private ScheduledExecutorService scheduledExecutor;

    /** Handle to a pending delayed-start task so it can be cancelled on stop(). */
    private volatile ScheduledFuture<?> pendingStartFuture;

    /**
     * Tick counter since the last sequencer start.
     * Written on the game thread; read by the overlay on the AWT thread.
     * AtomicInteger ensures the increment in onTick() is visible to readers
     * without the non-atomic read-modify-write of a plain volatile int.
     */
    private final AtomicInteger ticksSinceStart = new AtomicInteger(0);

    /**
     * The quantized target BPM currently loaded.
     * Written on the game thread; read by the overlay on the AWT thread — must be volatile.
     */
    @Getter
    private volatile float currentTargetBPM = 100f;

    /**
     * Last measured drift in microseconds (actual position − expected position).
     * Written on the game thread; read by the overlay on the AWT thread — must be volatile.
     */
    @Getter
    private volatile long lastDriftMicros = 0;

    /**
     * True once init() completes successfully.
     * Written on the game thread; read by the overlay on the AWT thread — must be volatile.
     */
    private volatile boolean initialized = false;

    /** The OSRS soundbank, cached so we can switch back to it without re-reading the stream. */
    private Soundbank osrsSoundfont = null;

    /** Whichever soundbank is currently loaded into the synthesizer. */
    private Soundbank loadedSoundbank = null;

    // ── Lifecycle ─────────────────────────────────────────────────────────────

    /**
     * Initialize with a soundfont from an InputStream.
     * Pass null to use Java's default soundbank.
     *
     * @param sf2Stream soundfont data, or {@code null} to use the system default
     */
    public void init(InputStream sf2Stream) throws Exception {
        synthesizer = MidiSystem.getSynthesizer();
        synthesizer.open();

        if (sf2Stream != null) {
            Soundbank osrsSoundbank = MidiSystem.getSoundbank(sf2Stream);
            Soundbank defaultSoundbank = synthesizer.getDefaultSoundbank();
            if (defaultSoundbank != null) {
                synthesizer.unloadAllInstruments(defaultSoundbank);
            }
            synthesizer.loadAllInstruments(osrsSoundbank);
            // Cache for switchSoundfont() calls
            this.osrsSoundfont = osrsSoundbank;
            loadedSoundbank = osrsSoundbank;
            log.info("OSRS soundfont loaded ({} instruments)", osrsSoundbank.getInstruments().length);
        } else {
            log.warn("No soundfont provided — using Java's default soundbank");
            loadedSoundbank = synthesizer.getDefaultSoundbank();
        }

        // Create sequencer NOT connected to the default device;
        // we'll wire it to our synthesizer manually.
        sequencer = MidiSystem.getSequencer(false);
        sequencer.open();
        // Route through BankFixReceiver to correct OSRS's non-standard CC32 bank selection.
        // Keep a reference so switchSoundfont() can rewire this transmitter later.
        activeTransmitter = sequencer.getTransmitter();
        activeTransmitter.setReceiver(new BankFixReceiver(synthesizer));

        // CRITICAL: Java's Gervill synthesizer hard-codes channel index 9 as percussion
        // (GM drum channel). OSRS doesn't follow GM conventions — it uses ALL 16 channels
        // for melodic content, assigning drums via program change like any other instrument.
        // We must explicitly switch every channel to melodic mode (setSolo/Mute won't help
        // here — the fix is to set the channel type via the synthesizer's MidiChannel API).
        // Calling programChange(0) on ch9 unlocks it from forced drum mode in Gervill.
        releaseGm10DrumChannel();

        // Loop tracks continuously by default
        sequencer.setLoopCount(Sequencer.LOOP_CONTINUOUSLY);

        // Executor for delayed-start (beat offset / ping compensation)
        scheduledExecutor = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r, "ticksync-beat-offset");
            t.setDaemon(true);
            return t;
        });

        initialized = true;
        log.info("MidiTickPlayer initialized");
    }

    /**
     * Java Sound's Gervill synthesizer treats MIDI channel index 9 as a dedicated
     * percussion channel regardless of Program Change messages sent to it. This is
     * GM-compliant but OSRS is NOT GM-compliant — it uses ch9 for melodic instruments.
     *
     * Calling programChange() directly on the MidiChannel object (bypassing the
     * sequencer) forces Gervill to re-evaluate the channel as melodic.
     */
    private void releaseGm10DrumChannel() {
        MidiChannel[] channels = synthesizer.getChannels();
        // Explicitly send a program change to every channel so Gervill initialises
        // them all in melodic mode. Channel 9 (index) gets the same treatment.
        for (MidiChannel channel : channels) {
            if (channel != null) {
                channel.programChange(0, 0); // bank 0, program 0 as starting state
            }
        }
        log.info("All 16 MIDI channels initialised in melodic mode (GM drum ch9 override applied)");
    }

    /**
     * Initialize with a soundfont file on disk.
     *
     * @param sf2File path to the .sf2 file, or {@code null} / non-existent to use system default
     */
    public void init(File sf2File) throws Exception {
        if (sf2File != null && sf2File.exists()) {
            try (InputStream is = new FileInputStream(sf2File)) {
                init(is);
            }
        } else {
            init((InputStream) null);
        }
    }

    // ── Playback control ──────────────────────────────────────────────────────

    /**
     * Load a quantized Sequence for playback.
     * Does NOT start immediately — playback begins on the next onTick() call,
     * ensuring alignment with a GameTick boundary.
     *
     * @param quantizedSequence the tempo-quantized sequence to load
     * @param targetBPM         the quantized target BPM (used for drift correction)
     */
    public void loadSequence(Sequence quantizedSequence, float targetBPM) throws Exception {
        if (!initialized) {
            log.warn("MidiTickPlayer not initialized, cannot load sequence");
            return;
        }

        if (sequencer.isRunning()) {
            sequencer.stop();
        }

        sequencer.setSequence(quantizedSequence);
        currentTargetBPM = targetBPM;
        pendingStart = true;
        ticksSinceStart.set(0);
        lastDriftMicros = 0;

        log.info("Sequence loaded — target BPM: {}", targetBPM);
    }

    /**
     * Called every GameTick (600 ms) from the plugin's onGameTick subscriber.
     *
     * <p>On the first tick after {@link #loadSequence}, starts playback aligned to the
     * tick boundary (optionally delayed by {@link #beatOffsetMs}).</p>
     *
     * <p>Drift correction uses a two-phase schedule:
     * <ul>
     *   <li><b>Aggressive</b> (ticks 0–{@value #AGGRESSIVE_TICKS}): checks every
     *       {@value #AGGRESSIVE_INTERVAL} ticks (~1.2 s) to lock in quickly after start.</li>
     *   <li><b>Normal</b> (ticks &gt; {@value #AGGRESSIVE_TICKS}): checks every
     *       {@value #NORMAL_INTERVAL} ticks (~4.8 s) for light ongoing maintenance.</li>
     * </ul>
     * A correction is only applied when drift exceeds {@value #DRIFT_THRESHOLD_MICROS} µs (20 ms).</p>
     */
    public void onTick() {
        if (!initialized || sequencer == null) {
            return;
        }

        if (pendingStart) {
            sequencer.setMicrosecondPosition(0);
            pendingStart = false;
            paused = false;
            ticksSinceStart.set(0);
            lastDriftMicros = 0;

            if (beatOffsetMs > 0 && scheduledExecutor != null && !scheduledExecutor.isShutdown()) {
                // Delay the actual sequencer start by beatOffsetMs so the beat lands
                // after the tick — compensates for low-ping players who click early.
                final float bpm = currentTargetBPM;
                pendingStartFuture = scheduledExecutor.schedule(
                        () -> {
                            sequencer.start();
                            sequencer.setTempoInBPM(bpm);
                            pendingStartFuture = null;
                        },
                        beatOffsetMs,
                        TimeUnit.MILLISECONDS);
                log.debug("Sequencer start delayed by {}ms (beat offset)", beatOffsetMs);
            } else {
                sequencer.start();
                sequencer.setTempoInBPM(currentTargetBPM);
            }
            return;
        }

        // Skip all processing when paused — position is retained for resume
        if (paused) {
            return;
        }

        if (!sequencer.isRunning()) {
            return;
        }

        ticksSinceStart.incrementAndGet();

        // Two-phase drift correction: aggressive near track start, normal thereafter.
        int ticks = ticksSinceStart.get();
        int interval = (ticks < AGGRESSIVE_TICKS) ? AGGRESSIVE_INTERVAL : NORMAL_INTERVAL;

        if (ticks % interval == 0) {
            long expectedMicros = ((long) ticks * TICK_DURATION_MICROS) - ((long) beatOffsetMs * 1000L);
            long actualMicros = sequencer.getMicrosecondPosition();
            lastDriftMicros = actualMicros - expectedMicros;

            if (Math.abs(lastDriftMicros) > DRIFT_THRESHOLD_MICROS) {
                sequencer.setMicrosecondPosition(expectedMicros);
                sequencer.setTempoInBPM(currentTargetBPM);
                log.debug(
                        "Drift corrected: {}ms → reset to {}µs (offset={}ms, tick={})",
                        lastDriftMicros / 1000,
                        expectedMicros,
                        beatOffsetMs,
                        ticks);
            }
        }
    }

    /**
     * Set playback volume. Range: 0.0 (silent) to 1.0 (max).
     * Uses MIDI CC7 (channel volume) on all 16 channels.
     *
     * @param volume normalised volume in [0.0, 1.0]
     */
    public void setVolume(float volume) {
        if (synthesizer == null || !synthesizer.isOpen()) {
            return;
        }

        int midiVolume = Math.round(Math.max(0f, Math.min(1f, volume)) * 127f);
        MidiChannel[] channels = synthesizer.getChannels();
        for (MidiChannel channel : channels) {
            if (channel != null) {
                channel.controlChange(7, midiVolume);
            }
        }
    }

    /**
     * Set the beat-offset delay in milliseconds.
     * The next scheduled start will be delayed by this amount.
     * If playback is already running, a forced drift correction on the next tick
     * will nudge the sequencer to the new expected position.
     *
     * @param ms delay in milliseconds (clamped to 0–1000)
     */
    public void setBeatOffset(int ms) {
        this.beatOffsetMs = Math.max(0, Math.min(1000, ms));
        // Drift will be caught at the next scheduled correction interval (at most 2 ticks away).
        log.debug("Beat offset set to {}ms", this.beatOffsetMs);
    }

    /**
     * Stop current playback without releasing resources.
     * Cancels any pending delayed-start task.
     */
    public void stop() {
        // Cancel any pending delayed-start before stopping the sequencer
        if (pendingStartFuture != null && !pendingStartFuture.isDone()) {
            pendingStartFuture.cancel(false);
            pendingStartFuture = null;
        }
        if (sequencer != null && sequencer.isRunning()) {
            sequencer.stop();
        }
        pendingStart = false;
        paused = false;
        ticksSinceStart.set(0);
        lastDriftMicros = 0;
    }

    /**
     * Pause playback, retaining the current position.
     * Has no effect if not currently playing.
     */
    public void pause() {
        if (sequencer != null && sequencer.isRunning() && !paused) {
            sequencer.stop();
            paused = true;
            log.info("MidiTickPlayer: paused at {}µs", sequencer.getMicrosecondPosition());
        }
    }

    /**
     * Resume from a paused state.
     * Has no effect if not paused.
     */
    public void resume() {
        if (paused && sequencer != null && sequencer.isOpen()) {
            sequencer.start();
            sequencer.setTempoInBPM(currentTargetBPM);
            paused = false;
            // Recalibrate tick counter so drift correction stays accurate
            ticksSinceStart.set((int) (sequencer.getMicrosecondPosition() / TICK_DURATION_MICROS));
            log.info("MidiTickPlayer: resumed (ticks recalibrated to {})", ticksSinceStart.get());
        }
    }

    // ── Status queries ────────────────────────────────────────────────────────

    /** @return {@code true} when playback is paused (position retained, not stopped). */
    public boolean isPaused() {
        return paused;
    }

    /** @return current tick count since last sequencer start. */
    public int getTicksSinceStart() {
        return ticksSinceStart.get();
    }

    /** @return {@code true} if a sequence has been loaded and is waiting for the next onTick() to start. */
    public boolean hasPendingStart() {
        return pendingStart;
    }

    /** @return {@code true} if the sequencer is actively playing. */
    public boolean isPlaying() {
        return initialized && sequencer != null && sequencer.isRunning();
    }

    /** @return {@code true} once {@link #init} has completed successfully. */
    public boolean isInitialized() {
        return initialized;
    }

    /** Current playback position in microseconds (0 when stopped or not initialised). */
    public long getMicrosecondPosition() {
        return (sequencer != null && sequencer.isOpen()) ? sequencer.getMicrosecondPosition() : 0L;
    }

    /** Total sequence length in microseconds (0 when no sequence is loaded). */
    public long getMicrosecondLength() {
        return (sequencer != null && sequencer.isOpen()) ? sequencer.getMicrosecondLength() : 0L;
    }

    /**
     * Seek to an absolute position in microseconds.
     * Keeps the playing/paused state — if the sequencer was running it resumes
     * from the new position; if paused the position is updated but playback stays paused.
     *
     * @param micros target position in microseconds (clamped to ≥ 0)
     */
    public void seekToMicros(long micros) {
        if (!initialized || sequencer == null || !sequencer.isOpen()) {
            return;
        }
        long clamped = Math.max(0L, micros);
        boolean wasRunning = sequencer.isRunning();
        if (wasRunning) {
            sequencer.stop();
        }
        sequencer.setMicrosecondPosition(clamped);
        if (wasRunning) {
            sequencer.start();
            sequencer.setTempoInBPM(currentTargetBPM);
        }
        // Recalibrate drift-correction counter
        ticksSinceStart.set((int) (clamped / TICK_DURATION_MICROS));
    }

    /**
     * Set whether the current/next sequence should loop continuously or play once.
     * Call before or after loadSequence() — the sequencer accepts setLoopCount at any time.
     *
     * @param loop {@code true} to loop indefinitely, {@code false} to play once
     */
    public void setLooping(boolean loop) {
        if (sequencer != null && sequencer.isOpen()) {
            sequencer.setLoopCount(loop ? Sequencer.LOOP_CONTINUOUSLY : 0);
        }
    }

    // ── Soundfont switching ────────────────────────────────────────────────────

    /**
     * Switch the synthesizer's active soundbank and rewire the sequencer's
     * receiver chain to match the requested mode.
     *
     * <ul>
     *   <li><b>OSRS</b>          — reload cached OSRS.sf2, route through
     *       {@link BankFixReceiver} (CC32→CC0 remap), call
     *       {@link #releaseGm10DrumChannel()} so ch9 is melodic.</li>
     *   <li><b>SYSTEM_DEFAULT</b> — reload Java's built-in GM bank, route
     *       directly to synthesizer. Ch9 stays as GM percussion.</li>
     *   <li><b>CUSTOM</b>        — load the .sf2 at {@code customSf2Path},
     *       route directly (GM conventions assumed). Falls back to
     *       SYSTEM_DEFAULT if the file is missing or unreadable.</li>
     * </ul>
     *
     * @param mode         the requested soundfont mode
     * @param customSf2Path filesystem path used only for {@code CUSTOM} mode
     */
    public void switchSoundfont(SoundfontMode mode, String customSf2Path) throws Exception {
        if (!initialized || synthesizer == null || !synthesizer.isOpen()) {
            log.warn("switchSoundfont: player not initialized, ignoring");
            return;
        }

        // ── 1. Unload current soundbank ──────────────────────────────────────
        if (loadedSoundbank != null) {
            synthesizer.unloadAllInstruments(loadedSoundbank);
            loadedSoundbank = null;
        }

        // ── 2. Load the new soundbank ────────────────────────────────────────
        boolean useOsrsChain = false; // whether to route through BankFixReceiver

        switch (mode) {
            case OSRS: {
                if (osrsSoundfont != null) {
                    synthesizer.loadAllInstruments(osrsSoundfont);
                    loadedSoundbank = osrsSoundfont;
                    log.info("Switched to OSRS soundfont ({} instruments)", osrsSoundfont.getInstruments().length);
                } else {
                    log.warn("switchSoundfont: OSRS soundfont not cached — falling back to system default");
                    loadSystemDefault();
                }
                useOsrsChain = true;
                break;
            }

            case SYSTEM_DEFAULT: {
                loadSystemDefault();
                break;
            }

            case CUSTOM: {
                Soundbank custom = loadCustomSoundfont(customSf2Path);
                if (custom != null) {
                    synthesizer.loadAllInstruments(custom);
                    loadedSoundbank = custom;
                } else {
                    // already logged inside loadCustomSoundfont; fall back gracefully
                    loadSystemDefault();
                }
                // CUSTOM follows GM conventions — no BankFixReceiver, no ch9 override
                break;
            }
        }

        // ── 3. Rewire transmitter chain ──────────────────────────────────────
        // Re-use the same Transmitter object; just swap its Receiver.
        if (activeTransmitter != null) {
            if (useOsrsChain) {
                activeTransmitter.setReceiver(new BankFixReceiver(synthesizer));
                // OSRS tracks use ch9 for melodic content — override Gervill's drum lock
                releaseGm10DrumChannel();
            } else {
                // Direct path: standard GM — ch9 keeps its percussion role
                activeTransmitter.setReceiver(synthesizer.getReceiver());
            }
        }
    }

    /** Load Java's built-in GM soundbank into the synthesizer. */
    private void loadSystemDefault() {
        Soundbank def = synthesizer.getDefaultSoundbank();
        if (def != null) {
            synthesizer.loadAllInstruments(def);
            loadedSoundbank = def;
            log.info("Switched to system default soundfont");
        } else {
            log.warn("switchSoundfont: no system default soundfont available");
        }
    }

    /**
     * Attempt to load a .sf2 file from the filesystem.
     * Returns {@code null} (with a warning) if the path is empty, the file
     * is missing, or it cannot be parsed as a soundfont — the caller should
     * fall back to {@code SYSTEM_DEFAULT} in those cases.
     *
     * @param path filesystem path to the .sf2 file
     * @return the loaded {@link Soundbank}, or {@code null} on failure
     */
    private Soundbank loadCustomSoundfont(String path) {
        if (path == null || path.trim().isEmpty()) {
            log.warn("Custom soundfont: path is empty — falling back to system default");
            return null;
        }

        File sf2File = new File(path.trim());
        if (!sf2File.exists()) {
            log.warn(
                    "Custom soundfont: file not found: {} — falling back to system default", sf2File.getAbsolutePath());
            return null;
        }

        try {
            Soundbank sb = MidiSystem.getSoundbank(sf2File);
            log.info("Custom soundfont loaded: {} ({} instruments)", sf2File.getName(), sb.getInstruments().length);
            return sb;
        } catch (Exception e) {
            log.warn(
                    "Custom soundfont: failed to load {} — falling back to system default. Error: {}",
                    sf2File.getName(),
                    e.getMessage());
            return null;
        }
    }

    // ── Shutdown ──────────────────────────────────────────────────────────────

    /**
     * Stop playback and release all MIDI resources.
     * Should be called from the plugin's shutDown() method.
     */
    public void shutdown() {
        // Cancel any pending delayed start
        if (pendingStartFuture != null && !pendingStartFuture.isDone()) {
            pendingStartFuture.cancel(false);
            pendingStartFuture = null;
        }
        if (scheduledExecutor != null && !scheduledExecutor.isShutdown()) {
            // shutdownNow() interrupts any running task to guarantee fast termination
            scheduledExecutor.shutdownNow();
        }
        if (sequencer != null) {
            if (sequencer.isRunning()) {
                sequencer.stop();
            }
            if (sequencer.isOpen()) {
                sequencer.close();
            }
        }
        if (synthesizer != null && synthesizer.isOpen()) {
            synthesizer.close();
        }
        initialized = false;
        log.info("MidiTickPlayer shut down");
    }
}

package com.ticksync.music;

/**
 * Controls how a source BPM is snapped to the nearest tick-aligned value
 * (valid set: 25, 50, 100, 200 BPM).
 */
public enum SnapMode {
    NEAREST("Snap nearest"),
    UP("Always snap up"),
    PREFER_UP("Prefer up");

    private final String name;

    SnapMode(String name) {
        this.name = name;
    }

    @Override
    public String toString() {
        return name;
    }
}

package com.ticksync.music;

import java.io.File;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import lombok.extern.slf4j.Slf4j;

/**
 * Downloads the OSRS soundfont on first run and caches it locally.
 *
 * <p>The .sf2 file is too large to bundle in the plugin JAR (31 MB vs the
 * Plugin Hub's 10 MB source-archive limit), so it is hosted as a GitHub
 * Release asset and downloaded into
 * {@code ~/.runelite/ticksync-cache/soundfont/}.
 */
@Slf4j
public final class SoundfontDownloader {

    private static final String DOWNLOAD_URL =
            "https://github.com/theOranguzang/osrs-ticksync-music"
                    + "/releases/download/soundfont-v1/OSRS.sf2.bin";

    private static final String CACHE_DIR_NAME = "ticksync-cache";
    private static final String SOUNDFONT_DIR_NAME = "soundfont";
    private static final String SOUNDFONT_FILE_NAME = "OSRS.sf2";

    /** Connection and read timeout in milliseconds. */
    private static final int TIMEOUT_MS = 60_000;

    private SoundfontDownloader() {
        // utility class
    }

    /**
     * Return the local cached soundfont file, downloading it first
     * if absent.
     *
     * @return the .sf2 {@link File}, or {@code null} if download failed
     */
    public static File ensureSoundfont() {
        File cacheDir = new File(
                System.getProperty("user.home")
                        + File.separator + ".runelite"
                        + File.separator + CACHE_DIR_NAME
                        + File.separator + SOUNDFONT_DIR_NAME);

        File sf2File = new File(cacheDir, SOUNDFONT_FILE_NAME);

        if (sf2File.exists() && sf2File.length() > 0) {
            log.debug("OSRS soundfont already cached at {}",
                    sf2File.getAbsolutePath());
            return sf2File;
        }

        log.info("OSRS soundfont not found locally"
                + " - downloading from GitHub release...");

        if (!cacheDir.exists() && !cacheDir.mkdirs()) {
            log.error(
                    "Failed to create soundfont cache directory: {}",
                    cacheDir.getAbsolutePath());
            return null;
        }

        // Download to temp file first, then rename
        // - avoids partial files on crash
        File tempFile = new File(
                cacheDir, SOUNDFONT_FILE_NAME + ".tmp");
        try {
            HttpURLConnection conn = (HttpURLConnection)
                    new URL(DOWNLOAD_URL).openConnection();
            conn.setConnectTimeout(TIMEOUT_MS);
            conn.setReadTimeout(TIMEOUT_MS);
            conn.setInstanceFollowRedirects(true);
            conn.setRequestProperty("User-Agent",
                    "TickSyncMusic-RuneLite-Plugin");

            int responseCode = conn.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                log.error(
                        "Soundfont download failed - HTTP {}",
                        responseCode);
                return null;
            }

            try (InputStream in = conn.getInputStream();
                    FileOutputStream out =
                            new FileOutputStream(tempFile)) {
                byte[] buf = new byte[8192];
                int bytesRead;
                while ((bytesRead = in.read(buf)) != -1) {
                    out.write(buf, 0, bytesRead);
                }
            }

            // Atomic rename
            if (!tempFile.renameTo(sf2File)) {
                log.error(
                        "Failed to rename temp soundfont to {}",
                        sf2File.getAbsolutePath());
                if (!tempFile.delete()) {
                    log.warn("Could not delete temp file: {}",
                            tempFile.getAbsolutePath());
                }
                return null;
            }

            log.info("OSRS soundfont downloaded to {} ({} MB)",
                    sf2File.getAbsolutePath(),
                    sf2File.length() / (1024 * 1024));
            return sf2File;

        } catch (Exception e) {
            log.error("Failed to download OSRS soundfont", e);
            if (!tempFile.delete()) {
                log.warn("Could not delete temp file: {}",
                        tempFile.getAbsolutePath());
            }
            return null;
        }
    }
}

package com.ticksync.music;

/**
 * Selects which soundfont is used for MIDI playback.
 * Applies to both OSRS cache tracks and custom MIDI folder tracks.
 *
 * OSRS           — loads OSRS.sf2 from classpath; sounds like RuneScape.
 *                  Channel-9 drum remap and BankFixReceiver are active so
 *                  OSRS MIDI bank-selection works correctly.
 * SYSTEM_DEFAULT — Java's built-in GM soundfont; standard GM instrument mapping.
 *                  Channel 9 stays as GM percussion (no remap, no BankFixReceiver).
 * CUSTOM         — user-supplied .sf2 file from the configured path.
 *                  Treated like SYSTEM_DEFAULT (GM conventions assumed;
 *                  no channel-9 remap, no BankFixReceiver).
 */
public enum SoundfontMode {
    OSRS("OSRS"),
    SYSTEM_DEFAULT("System default"),
    CUSTOM("Custom file");

    private final String name;

    SoundfontMode(String name) {
        this.name = name;
    }

    @Override
    public String toString() {
        return name;
    }
}

package com.ticksync.music;

import javax.sound.midi.InvalidMidiDataException;
import javax.sound.midi.MetaMessage;
import javax.sound.midi.MidiEvent;
import javax.sound.midi.MidiMessage;
import javax.sound.midi.Sequence;
import javax.sound.midi.ShortMessage;
import javax.sound.midi.Track;
import lombok.extern.slf4j.Slf4j;

/**
 * Pure MIDI sequence preprocessing utility.
 *
 * Two operations applied in-memory before the sequence reaches the sequencer:
 *
 * 1. Tempo quantization — snaps all SET_TEMPO meta-events to valid tick-aligned
 *    BPMs (25, 50, 100, or 200) so every beat lands on a 600 ms game-tick boundary.
 *
 * 2. Channel 9 remap — moves all events on MIDI channel index 9 to channel 13.
 *    Java's Gervill synthesizer permanently hardcodes channel 9 as GM percussion
 *    and ignores all attempts to override it. OSRS uses channel 9 for melodic
 *    content. Remapping to channel 13 (unused in typical OSRS tracks) sidesteps
 *    the lock entirely.
 *    NOTE: channel 15 is used by 556.mid (program 45), so 13 is the safe target.
 */
@Slf4j
public class TempoQuantizer {
    // ── Constants ─────────────────────────────────────────────────────────────

    /** Valid tick-aligned BPMs: multiples of the 100 BPM base (600 ms/tick). */
    private static final float[] VALID_BPMS = {25f, 50f, 100f, 200f};

    /** Channel Gervill hardcodes as percussion (GM channel 10, 0-indexed). */
    private static final int GERVILL_DRUM_CHANNEL = 9;

    /**
     * Target channel for remapped events.
     * Channel 15 (0-indexed) bypasses Gervill's hardcoded GM drum lock on channel 9.
     */
    private static final int REMAP_TARGET_CHANNEL = 15;

    /** MIDI meta-event type for SET_TEMPO (0x51 = 81). */
    private static final int META_SET_TEMPO = 0x51;

    /** Microseconds per minute — used to convert between BPM and µs-per-beat. */
    private static final float MICROS_PER_MINUTE = 60_000_000f;

    /**
     * Minimum percentage drop from source BPM before PREFER_UP forces a snap-up.
     * E.g. 0.15 = if the nearest valid BPM is more than 15 % below the source, snap up.
     */
    private static final float PREFER_UP_THRESHOLD = 0.15f;

    // ── Main entry point ──────────────────────────────────────────────────────

    /**
     * Apply tempo quantization and (optionally) channel-9 remap in one pass.
     *
     * @param original       source sequence (not mutated)
     * @param snapMode       how to snap the source BPM to a valid tick-aligned value
     * @param remapChannel9  pass {@code true} when using the OSRS soundfont (Gervill drum-lock
     *                       workaround); pass {@code false} for the system-default GM soundfont
     *                       where channel 9 should stay as standard GM percussion.
     * @return a new, preprocessed Sequence ready for playback
     */
    public static Sequence process(Sequence original, SnapMode snapMode, boolean remapChannel9)
            throws InvalidMidiDataException {
        log.info(
                "TempoQuantizer.process() — snapMode={} remapCh9={}{}",
                snapMode,
                remapChannel9,
                remapChannel9 ? " → ch" + REMAP_TARGET_CHANNEL : "");
        Sequence quantized = quantize(original, snapMode);
        return remapChannel9 ? remapDrumChannel(quantized) : quantized;
    }

    /**
     * Apply both tempo quantization AND channel-9 remap.
     * Uses the supplied SnapMode when snapping tempo events.
     *
     * @param original  source sequence (not mutated)
     * @param snapMode  BPM snap strategy
     * @return preprocessed Sequence
     */
    public static Sequence process(Sequence original, SnapMode snapMode) throws InvalidMidiDataException {
        return process(original, snapMode, true);
    }

    /**
     * Convenience overload — uses NEAREST snap and remaps channel 9.
     *
     * @param original source sequence (not mutated)
     * @return preprocessed Sequence
     */
    public static Sequence process(Sequence original) throws InvalidMidiDataException {
        return process(original, SnapMode.NEAREST, true);
    }

    // ── Tempo quantization ────────────────────────────────────────────────────

    /**
     * Snap a BPM to the nearest valid tick-aligned value using the given SnapMode.
     *
     * <ul>
     *   <li><b>NEAREST</b> — pick the closest value from {25, 50, 100, 200}.</li>
     *   <li><b>UP</b>      — smallest valid BPM ≥ sourceBPM; clamps to 200 if above all.</li>
     *   <li><b>PREFER_UP</b> — nearest, but if the nearest is <em>below</em> the source
     *       and the percentage decrease exceeds {@value #PREFER_UP_THRESHOLD}, snap up
     *       to the next valid BPM above the source instead.</li>
     * </ul>
     *
     * Examples (PREFER_UP):
     * <pre>
     *   90  → 100 (nearest is 100, 11% up     — fine)
     *   60  → 100 (nearest is  50, 17% down   — exceeds threshold → snap up to 100)
     *   45  →  50 (nearest is  50, 11% up     — fine)
     *  110  → 100 (nearest is 100,  9% down   — within threshold)
     *  130  → 200 (nearest is 100, 23% down   — exceeds threshold → snap up to 200)
     * </pre>
     *
     * @param sourceBPM the raw BPM from the MIDI file
     * @param snapMode  the desired snap strategy
     * @return a value from {@link #VALID_BPMS}
     */
    public static float quantize(float sourceBPM, SnapMode snapMode) {
        switch (snapMode) {
            case UP:
                // Smallest valid BPM that is >= sourceBPM (VALID_BPMS is sorted ascending)
                for (float v : VALID_BPMS) {
                    if (v >= sourceBPM) {
                        return v;
                    }
                }
                return VALID_BPMS[VALID_BPMS.length - 1]; // sourceBPM > 200 → clamp to 200

            case PREFER_UP: {
                float nearest = quantize(sourceBPM, SnapMode.NEAREST);
                // If nearest is below the source AND the drop exceeds the threshold, snap up instead
                if (nearest < sourceBPM && (sourceBPM - nearest) / sourceBPM > PREFER_UP_THRESHOLD) {
                    return quantize(sourceBPM, SnapMode.UP);
                }
                return nearest;
            }

            case NEAREST:
            default: {
                float closest = 100f;
                float minDist = Float.MAX_VALUE;
                for (float v : VALID_BPMS) {
                    float dist = Math.abs(sourceBPM - v);
                    if (dist < minDist) {
                        minDist = dist;
                        closest = v;
                    }
                }
                return closest;
            }
        }
    }

    /**
     * Convenience overload — uses NEAREST snap.
     *
     * @param sourceBPM the raw BPM from the MIDI file
     * @return a value from {@link #VALID_BPMS}
     */
    public static float quantize(float sourceBPM) {
        return quantize(sourceBPM, SnapMode.NEAREST);
    }

    /**
     * Create a copy of the Sequence with all SET_TEMPO meta-events replaced
     * with their tick-aligned equivalents, using the given SnapMode.
     *
     * @param original  source sequence (not mutated)
     * @param snapMode  BPM snap strategy
     * @return new Sequence with quantized tempo events
     */
    public static Sequence quantize(Sequence original, SnapMode snapMode) throws InvalidMidiDataException {
        Sequence out = new Sequence(original.getDivisionType(), original.getResolution());

        for (Track track : original.getTracks()) {
            Track newTrack = out.createTrack();
            for (int i = 0; i < track.size(); i++) {
                MidiEvent event = track.get(i);
                MidiMessage msg = event.getMessage();

                if (msg instanceof MetaMessage) {
                    MetaMessage meta = (MetaMessage) msg;
                    if (meta.getType() == META_SET_TEMPO) {
                        byte[] data = meta.getData();
                        int microsPerBeat = ((data[0] & 0xFF) << 16) | ((data[1] & 0xFF) << 8) | (data[2] & 0xFF);
                        float sourceBPM = MICROS_PER_MINUTE / microsPerBeat;
                        float targetBPM = quantize(sourceBPM, snapMode);
                        int newMicros = Math.round(MICROS_PER_MINUTE / targetBPM);

                        byte[] newData = {
                            (byte) ((newMicros >> 16) & 0xFF),
                            (byte) ((newMicros >> 8) & 0xFF),
                            (byte) (newMicros & 0xFF)
                        };
                        MetaMessage newMeta = new MetaMessage();
                        newMeta.setMessage(META_SET_TEMPO, newData, 3);
                        newTrack.add(new MidiEvent(newMeta, event.getTick()));
                        log.debug("Tempo snapped: {} → {} BPM ({})", sourceBPM, targetBPM, snapMode);
                        continue;
                    }
                }
                newTrack.add(event);
            }
        }
        return out;
    }

    /**
     * Convenience overload — uses NEAREST snap.
     *
     * @param original source sequence (not mutated)
     * @return new Sequence with quantized tempo events
     */
    public static Sequence quantize(Sequence original) throws InvalidMidiDataException {
        return quantize(original, SnapMode.NEAREST);
    }

    // ── Channel 9 → REMAP_TARGET_CHANNEL remap ────────────────────────────────

    /**
     * Create a copy of the Sequence with every ShortMessage on channel 9
     * moved to {@link #REMAP_TARGET_CHANNEL}.
     *
     * Gervill locks channel 9 as drums regardless of Program Change messages
     * or direct MidiChannel API calls. Moving the data to an unused channel is
     * the only reliable workaround.
     *
     * New ShortMessage objects are created (ShortMessage is effectively
     * immutable after construction — you cannot change the channel in-place).
     *
     * @param original source sequence (not mutated)
     * @return new Sequence with ch9 events remapped
     */
    public static Sequence remapDrumChannel(Sequence original) throws InvalidMidiDataException {
        log.debug(
                "remapDrumChannel() called — scanning for ch{} events to move to ch{}",
                GERVILL_DRUM_CHANNEL,
                REMAP_TARGET_CHANNEL);

        Sequence out = new Sequence(original.getDivisionType(), original.getResolution());
        int remapped = 0;

        for (Track track : original.getTracks()) {
            Track newTrack = out.createTrack();
            for (int i = 0; i < track.size(); i++) {
                MidiEvent event = track.get(i);
                MidiMessage msg = event.getMessage();

                if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;
                    if (sm.getChannel() == GERVILL_DRUM_CHANNEL) {
                        // Create a brand-new ShortMessage on the target channel.
                        // ShortMessage channel cannot be changed after construction.
                        ShortMessage fixed = new ShortMessage(
                                sm.getCommand(), // e.g. 0x90 (NOTE_ON)
                                REMAP_TARGET_CHANNEL, // 15 instead of 9 — bypasses Gervill drum lock
                                sm.getData1(), // pitch / CC number
                                sm.getData2() // velocity / CC value
                                );
                        newTrack.add(new MidiEvent(fixed, event.getTick()));
                        remapped++;
                        continue;
                    }
                }
                newTrack.add(event);
            }
        }

        log.debug(
                "remapDrumChannel() done — remapped {} events from ch{} → ch{}",
                remapped,
                GERVILL_DRUM_CHANNEL,
                REMAP_TARGET_CHANNEL);

        return out;
    }

    // ── Utility ───────────────────────────────────────────────────────────────

    /**
     * Read the BPM from the first SET_TEMPO event in a Sequence.
     * Returns 100f if no tempo event is found.
     *
     * @param sequence the sequence to inspect
     * @return BPM derived from the first SET_TEMPO meta-event, or 100f if absent
     */
    public static float getFirstTempoBPM(Sequence sequence) {
        for (Track track : sequence.getTracks()) {
            for (int i = 0; i < track.size(); i++) {
                MidiEvent event = track.get(i);
                MidiMessage msg = event.getMessage();
                if (msg instanceof MetaMessage) {
                    MetaMessage meta = (MetaMessage) msg;
                    if (meta.getType() == META_SET_TEMPO) {
                        byte[] data = meta.getData();
                        int microsPerBeat = ((data[0] & 0xFF) << 16) | ((data[1] & 0xFF) << 8) | (data[2] & 0xFF);
                        return MICROS_PER_MINUTE / microsPerBeat;
                    }
                }
            }
        }
        return 100f;
    }
}

package com.ticksync.music;

