 *
 * Layout (top → bottom):
 *   TickSync Music  (header)
 *   Now Playing card  (track / status / BPM / drift)
 *   Mode toggle  [Game Music] [Jukebox]
 *   Transport  [⏮] [⏸] [⏹] [⏭]
 *   Seek bar  ▕███░░░░▏ 1:23 / 5:00
 *   ── Sound ──
 *     Volume slider
 *     Soundfont  [combo]
 *     Path  [field][…]   (only when Custom File)
 *     Tempo Snap  [combo]
 *     ☑ Mute in-game music
 *   ── Jukebox Settings ──  (only in Jukebox mode)
 *     Folder  [field][…]
 *     Play Mode  [combo]
 *   ── Tracks ──
 *     scrollable track list
 */
public class TickSyncMusicPanel extends PluginPanel {
    private static final String CFG_GROUP = "ticksyncmusic";
    private static final Color PANEL_BG = ColorScheme.DARK_GRAY_COLOR;
    private static final Color CARD_BG = ColorScheme.DARKER_GRAY_COLOR;
    private static final Color BORDER_COL = ColorScheme.MEDIUM_GRAY_COLOR;
    private static final Color TEXT_DIM = ColorScheme.LIGHT_GRAY_COLOR;
    private static final Color ORANGE = ColorScheme.BRAND_ORANGE;

    private final TickSyncMusicPlugin plugin;
    private final ConfigManager configManager;

    // ── Now Playing ─────────────────────────────────────────────────────────
    private final JLabel trackNameLabel = makeValueLabel("—");
    private final JLabel statusLabel = makeValueLabel("Stopped");
    private final JLabel bpmLabel = makeValueLabel("—");
    private final JLabel driftLabel = makeValueLabel("—");
    private final JLabel offsetLabel = makeValueLabel("—");

    // ── Mode toggle ──────────────────────────────────────────────────────────
    private final JToggleButton gameMusicBtn = new JToggleButton("Game Music");
    private final JToggleButton jukeboxBtn = new JToggleButton("Jukebox");

    // ── Transport ────────────────────────────────────────────────────────────
    private final JButton prevBtn = makeTransportBtn("⏮");
    private final JButton playPauseBtn = makeTransportBtn("▶");
    private final JButton stopBtn = makeTransportBtn("⏹");
    private final JButton nextBtn = makeTransportBtn("⏭");

    // ── Seek bar ─────────────────────────────────────────────────────────────
    /** Custom-painted progress canvas; assigned in buildSeekBar(). */
    private JPanel seekBarCanvas;

    private final JLabel seekTimeLabel = makeValueLabel("—");
    private long seekPosMicros = 0L;
    private long seekLenMicros = 0L;

    // ── Sound section ────────────────────────────────────────────────────────
    private final JSlider volumeSlider = new JSlider(0, 100, 50);
    private final JLabel volumeValueLabel = makeValueLabel("50");
    private final JComboBox<SoundfontMode> soundfontCombo = new JComboBox<>(SoundfontMode.values());
    private final JTextField soundfontPathField = new JTextField();
    /** Wrapper for the path field row + its gap — toggled with soundfont mode. */
    private JPanel soundfontPathSection;

    private final JComboBox<SnapMode> snapModeCombo = new JComboBox<>(SnapMode.values());
    private final JSlider beatOffsetSlider = new JSlider(0, 300, 0);
    private final JLabel beatOffsetLabel = dimLabel("Beat Offset: 0 ms");
    private final JCheckBox muteCheckBox = new JCheckBox("Mute in-game music");
    private final JCheckBox normalizeVolumeCheckBox = new JCheckBox("Normalize volume");
    private final JCheckBox compressDynamicsCheckBox = new JCheckBox("Compress dynamics");

    // ── Jukebox settings ─────────────────────────────────────────────────────
    private final JPanel jukeboxPanel = new JPanel();
    private final JTextField midiPathField = new JTextField();
    private final JComboBox<CustomPlayMode> playModeCombo = new JComboBox<>(CustomPlayMode.values());

    // ── Track list ───────────────────────────────────────────────────────────
    private final DefaultListModel<String> trackListModel = new DefaultListModel<>();
    private final JList<String> trackList = new JList<>(trackListModel);
    private final List<File> trackFiles = new ArrayList<>();

    // ── State ────────────────────────────────────────────────────────────────
    private boolean updatingControls = false;

    // ────────────────────────────────────────────────────────────────────────

    public TickSyncMusicPanel(TickSyncMusicPlugin plugin, ConfigManager configManager) {
        this.plugin = plugin;
        this.configManager = configManager;

        setBackground(PANEL_BG);

        JPanel content = new JPanel();
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(PANEL_BG);
        content.setBorder(new EmptyBorder(10, 10, 10, 10));

        content.add(buildHeader());
        content.add(vgap(8));
        content.add(buildNowPlayingCard());
        content.add(vgap(8));
        content.add(buildModeToggle());
        content.add(vgap(6));
        content.add(buildTransport());
        content.add(vgap(4));
        content.add(buildSeekBar());
        content.add(vgap(8));
        content.add(buildSoundSection());
        content.add(vgap(8));
        content.add(buildJukeboxPanel());

        add(content, BorderLayout.NORTH);

        initState();
    }

    // ── Section builders ─────────────────────────────────────────────────────

    private JLabel buildHeader() {
        JLabel title = new JLabel("TickSync Music");
        title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
        title.setForeground(Color.WHITE);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        return title;
    }

    private JPanel buildNowPlayingCard() {
        JPanel card = new JPanel(new GridLayout(5, 1, 0, 3));
        card.setBackground(CARD_BG);
        card.setBorder(new CompoundBorder(new MatteBorder(1, 1, 1, 1, BORDER_COL), new EmptyBorder(8, 8, 8, 8)));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 112));

        card.add(infoRow("Track:", trackNameLabel));
        card.add(infoRow("Status:", statusLabel));
        card.add(infoRow("BPM:", bpmLabel));
        card.add(infoRow("Drift:", driftLabel));
        card.add(infoRow("Offset:", offsetLabel));

        statusLabel.setForeground(Color.RED);
        return card;
    }

    private JPanel buildModeToggle() {
        ButtonGroup group = new ButtonGroup();
        group.add(gameMusicBtn);
        group.add(jukeboxBtn);

        styleToggle(gameMusicBtn);
        styleToggle(jukeboxBtn);

        gameMusicBtn.addActionListener(e -> {
            if (!updatingControls && gameMusicBtn.isSelected()) switchMode(false);
        });
        jukeboxBtn.addActionListener(e -> {
            if (!updatingControls && jukeboxBtn.isSelected()) switchMode(true);
        });

        JPanel row = fixedHeightPanel(new GridLayout(1, 2, 4, 0), 30);
        row.add(gameMusicBtn);
        row.add(jukeboxBtn);
        return row;
    }

    private JPanel buildTransport() {
        prevBtn.addActionListener(e -> plugin.prevTrack());
        playPauseBtn.addActionListener(e -> plugin.togglePlayPause());
        stopBtn.addActionListener(e -> plugin.stopPlayback());
        nextBtn.addActionListener(e -> plugin.nextTrack());

        JPanel row = fixedHeightPanel(new GridLayout(1, 4, 4, 0), 34);
        row.add(prevBtn);
        row.add(playPauseBtn);
        row.add(stopBtn);
        row.add(nextBtn);
        return row;
    }

    private JPanel buildSeekBar() {
        // Custom-painted bar so we control colour exactly
        seekBarCanvas = new JPanel() {
            @Override
            protected void paintComponent(Graphics g) {
                super.paintComponent(g);
                int w = getWidth();
                int h = getHeight();

                g.setColor(CARD_BG);
                g.fillRect(0, 0, w, h);

                if (seekLenMicros > 0) {
                    int fillW = (int) Math.round((double) seekPosMicros / seekLenMicros * w);
                    fillW = Math.max(0, Math.min(fillW, w));
                    g.setColor(ORANGE);
                    g.fillRect(0, 0, fillW, h);
                }

                g.setColor(BORDER_COL);
                g.drawRect(0, 0, w - 1, h - 1);
            }
        };
        seekBarCanvas.setBackground(CARD_BG);
        seekBarCanvas.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        seekBarCanvas.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                int w = seekBarCanvas.getWidth();
                if (w <= 0 || seekLenMicros <= 0) {
                    return;
                }
                double frac = Math.max(0.0, Math.min(1.0, (double) e.getX() / w));
                plugin.seekToMicros((long) (frac * seekLenMicros));
            }
        });

        seekTimeLabel.setForeground(TEXT_DIM);
        seekTimeLabel.setFont(seekTimeLabel.getFont().deriveFont(10f));
        seekTimeLabel.setHorizontalAlignment(SwingConstants.RIGHT);
        seekTimeLabel.setPreferredSize(new Dimension(90, 14));

        // The outer row: bar fills centre, time label on the right
        JPanel outer = fixedHeightPanel(new BorderLayout(6, 0), 18);
        outer.add(seekBarCanvas, BorderLayout.CENTER);
        outer.add(seekTimeLabel, BorderLayout.EAST);
        return outer;
    }

    private JPanel buildSoundSection() {
        JPanel section = new JPanel();
        section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
        section.setBackground(PANEL_BG);
        section.setAlignmentX(Component.LEFT_ALIGNMENT);

        // ── Section header ────────────────────────────────────────────────────
        JLabel hdr = dimLabel("Sound");
        hdr.setBorder(new CompoundBorder(new MatteBorder(1, 0, 0, 0, BORDER_COL), new EmptyBorder(4, 0, 4, 0)));
        hdr.setAlignmentX(Component.LEFT_ALIGNMENT);
        hdr.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        section.add(hdr);
        section.add(vgap(4));

        // ── Volume ───────────────────────────────────────────────────────────
        section.add(buildVolumeRow());
        section.add(vgap(6));

        // ── Soundfont combo ──────────────────────────────────────────────────
        soundfontCombo.setBackground(CARD_BG);
        soundfontCombo.setForeground(Color.WHITE);
        soundfontCombo.setBorder(BorderFactory.createLineBorder(BORDER_COL));
        soundfontCombo.addActionListener(e -> {
            if (!updatingControls) {
                SoundfontMode m = (SoundfontMode) soundfontCombo.getSelectedItem();
                if (m != null) {
                    configManager.setConfiguration(CFG_GROUP, "soundfontMode", m.name());
                    updateSoundfontPathVisibility(m);
                }
            }
        });

        JPanel sfRow = new JPanel(new BorderLayout(4, 0));
        sfRow.setBackground(PANEL_BG);
        sfRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        sfRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        JLabel sfLbl = dimLabel("Soundfont");
        sfLbl.setPreferredSize(new Dimension(70, 18));
        sfRow.add(sfLbl, BorderLayout.WEST);
        sfRow.add(soundfontCombo, BorderLayout.CENTER);
        section.add(sfRow);

        // ── Soundfont path row (shown only for CUSTOM) ───────────────────────
        soundfontPathField.setBackground(CARD_BG);
        soundfontPathField.setForeground(Color.WHITE);
        soundfontPathField.setCaretColor(Color.WHITE);
        soundfontPathField.setBorder(BorderFactory.createLineBorder(BORDER_COL));
        soundfontPathField.addActionListener(
                e -> applySoundfontPath(soundfontPathField.getText().trim()));

        JButton sfBrowse = new JButton("…");
        sfBrowse.setPreferredSize(new Dimension(30, 22));
        sfBrowse.setBackground(CARD_BG);
        sfBrowse.setForeground(TEXT_DIM);
        sfBrowse.setBorder(BorderFactory.createLineBorder(BORDER_COL));
        sfBrowse.setFocusPainted(false);
        sfBrowse.addActionListener(e -> browseForSoundfont());

        JPanel innerPathRow = new JPanel(new BorderLayout(4, 0));
        innerPathRow.setBackground(PANEL_BG);
        innerPathRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        innerPathRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        JLabel pathLbl = dimLabel("Path:");
        pathLbl.setPreferredSize(new Dimension(36, 18));
        innerPathRow.add(pathLbl, BorderLayout.WEST);
        innerPathRow.add(soundfontPathField, BorderLayout.CENTER);
        innerPathRow.add(sfBrowse, BorderLayout.EAST);

        // Wrapper so gap disappears along with the row when hidden
        soundfontPathSection = new JPanel();
        soundfontPathSection.setLayout(new BoxLayout(soundfontPathSection, BoxLayout.Y_AXIS));
        soundfontPathSection.setBackground(PANEL_BG);
        soundfontPathSection.setAlignmentX(Component.LEFT_ALIGNMENT);
