    /**
     * Refresh the Now Playing card and seek bar.
     * Must only be called on the EDT (wrap with SwingUtilities.invokeLater at call site).
     */
    public void updateNowPlaying(String trackName, String status, float sourceBPM, float targetBPM, long driftMs) {
        trackNameLabel.setText((trackName != null && !trackName.isEmpty()) ? trackName : "—");

        statusLabel.setText(status);
        switch (status) {
            case "Playing":
                statusLabel.setForeground(Color.GREEN);
                break;
            case "Paused":
                statusLabel.setForeground(Color.YELLOW);
                break;
            default:
                statusLabel.setForeground(Color.RED);
                break;
        }

        if (sourceBPM > 0 && targetBPM > 0) {
            bpmLabel.setText(String.format("%.0f → %.0f", sourceBPM, targetBPM));
        } else {
            bpmLabel.setText("—");
        }

        if (sourceBPM > 0) {
            driftLabel.setText(driftMs + " ms");
            driftLabel.setForeground(Math.abs(driftMs) > 50 ? Color.RED : Color.GREEN);
        } else {
            driftLabel.setText("—");
            driftLabel.setForeground(Color.WHITE);
        }

        // Beat offset
        int offsetMs = plugin.getBeatOffsetMs();
        offsetLabel.setText(offsetMs > 0 ? offsetMs + " ms" : "—");
        offsetLabel.setForeground(offsetMs > 0 ? Color.YELLOW : Color.WHITE);

        // Play/pause button icon
        MidiTickPlayer player = plugin.getMidiTickPlayer();
        playPauseBtn.setText((player != null && player.isPlaying()) ? "⏸" : "▶");

        // Seek bar
        if (player != null && player.isInitialized()) {
            seekPosMicros = player.getMicrosecondPosition();
            seekLenMicros = player.getMicrosecondLength();
        } else {
            seekPosMicros = 0L;
            seekLenMicros = 0L;
        }
        if (seekBarCanvas != null) {
            seekBarCanvas.repaint();
        }
        seekTimeLabel.setText(
                seekLenMicros > 0 ? formatMicros(seekPosMicros) + " / " + formatMicros(seekLenMicros) : "—");

        // Track-list highlight
        if (!trackListModel.isEmpty()) {
            int idx = plugin.getCurrentTrackIndex();
            if (idx >= 0 && idx < trackListModel.size() && trackList.getSelectedIndex() != idx) {
                trackList.setSelectedIndex(idx);
                trackList.ensureIndexIsVisible(idx);
            }
            trackList.repaint();
        }
    }

    /**
     * Refresh the track list from a folder path.
     * Safe to call from the game thread — callers must already wrap in SwingUtilities.invokeLater.
     */
    public void refreshTrackList(String folderPath) {
        trackFiles.clear();
        trackListModel.clear();

        if (folderPath == null || folderPath.trim().isEmpty()) {
            return;
        }

        File dir = new File(folderPath.trim());
        if (!dir.exists() || !dir.isDirectory()) {
            return;
        }

        File[] files = dir.listFiles((d, name) -> name.toLowerCase(Locale.ROOT).endsWith(".mid"));
        if (files == null || files.length == 0) {
            return;
        }

        List<File> sorted = new ArrayList<>(Arrays.asList(files));
        sorted.sort((a, b) -> a.getName().compareToIgnoreCase(b.getName()));

        for (File f : sorted) {
            trackFiles.add(f);
            String name = f.getName();
            int dot = name.lastIndexOf('.');
            trackListModel.addElement(dot > 0 ? name.substring(0, dot) : name);
        }
    }

