    private void browseForFolder() {
        JFileChooser chooser = new JFileChooser();
        chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);
        String current = midiPathField.getText().trim();
        if (!current.isEmpty()) {
            File cur = new File(current);
            if (cur.isDirectory()) {
                chooser.setCurrentDirectory(cur);
            }
        }
        if (chooser.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            applyFolderPath(chooser.getSelectedFile().getAbsolutePath());
        }
    }

    private void browseForSoundfont() {
        JFileChooser chooser = new JFileChooser();
        chooser.setFileSelectionMode(JFileChooser.FILES_ONLY);
        chooser.setFileFilter(new FileNameExtensionFilter("SoundFont files (*.sf2)", "sf2"));
        String current = soundfontPathField.getText().trim();
        if (!current.isEmpty()) {
            File cur = new File(current);
            chooser.setCurrentDirectory(cur.isDirectory() ? cur : cur.getParentFile());
        }
        if (chooser.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            applySoundfontPath(chooser.getSelectedFile().getAbsolutePath());
        }
    }

    private void applyFolderPath(String path) {
        midiPathField.setText(path);
        configManager.setConfiguration(CFG_GROUP, "customMidiFolder", path);
        refreshTrackList(path);
    }

    private void applySoundfontPath(String path) {
        soundfontPathField.setText(path);
        configManager.setConfiguration(CFG_GROUP, "customSoundfontPath", path);
    }

    private static String formatMicros(long micros) {
        long totalSecs = micros / 1_000_000L;
        long mins = totalSecs / 60;
        long secs = totalSecs % 60;
        return String.format("%d:%02d", mins, secs);
    }

