/**
 * TickSync Music — locks OSRS music to the game-tick grid.
 *
 * Every OSRS game tick is exactly 600ms = 100 BPM.
 * This plugin replaces the game's native music with MIDI playback
 * whose tempo has been quantized to a tick-aligned BPM (25/50/100/200),
 * so beats land exactly on tick boundaries.
 *
 * Architecture:
 *   TrackDetector  — watches the music widget for track changes
 *   TempoQuantizer — rewrites MIDI tempo events to tick-aligned BPMs
 *   MidiTickPlayer — plays the quantized MIDI synced to GameTick events
 *   TickSyncOverlay — optional debug HUD
 */
@Slf4j
@PluginDescriptor(
        name = "TickSync Music",
        description = "Tempo-syncs OSRS music to the game tick for rhythm-based gameplay",
        tags = {"music", "midi", "tick", "tempo", "sync", "rhythm", "tob"})
public class TickSyncMusicPlugin extends Plugin {

    @Inject
    private Client client;

    @Inject
    private TickSyncMusicConfig config;

    @Inject
    private ConfigManager configManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private TickSyncOverlay overlay;

    @Inject
    private KeyManager keyManager;

    @Inject
    private ClientToolbar clientToolbar;

    @Getter
    private MidiTickPlayer midiTickPlayer;

    @Getter
    private TrackDetector trackDetector;

    @Getter
    private CustomMidiPlayer customMidiPlayer;

    @Getter
    private CacheMidiLoader cacheMidiLoader;

    /** Sidebar panel shown in RuneLite's navigation toolbar. */
    private TickSyncMusicPanel panel;

    private NavigationButton navButton;

    /** Stores the player's music volume before we muted it, so we can restore on shutdown. */
    private int originalMusicVolume = -1;

    /** Tracks whether we have actively set the game music volume to 0. */
    private boolean gameMusicMuted = false;

    private boolean playerInitialized = false;

    /**
     * True once we've loaded the first jukebox track this session.
     * Distinguishes "never started" (load first track) from "just finished" (load next track).
     */
    private boolean jukeboxModeStarted = false;

    /** Source BPM of the currently loaded track (before quantization), for the panel display. */
    private float currentSourceBPM = 0f;

    // ── Hotkey listeners ────────────────────────────────────────────────────

    private final HotkeyListener playPauseListener = new HotkeyListener(() -> config.hotkeyPlayPause()) {
        @Override
        public void hotkeyPressed() {
            togglePlayPause();
        }
    };

    private final HotkeyListener nextListener = new HotkeyListener(() -> config.hotkeyNext()) {
        @Override
        public void hotkeyPressed() {
            nextTrack();
        }
    };

    private final HotkeyListener prevListener = new HotkeyListener(() -> config.hotkeyPrev()) {
        @Override
        public void hotkeyPressed() {
            prevTrack();
        }
    };

    private final HotkeyListener stopListener = new HotkeyListener(() -> config.hotkeyStop()) {
        @Override
        public void hotkeyPressed() {
            stopPlayback();
        }
    };

    // ── Lifecycle ───────────────────────────────────────────────────────

    @Override
    protected void startUp() throws Exception {
        log.info("TickSync Music starting up…");

        midiTickPlayer = new MidiTickPlayer();
        trackDetector = new TrackDetector(client);
        trackDetector.setOnTrackChange(this::onTrackChanged);
        customMidiPlayer = new CustomMidiPlayer();
        cacheMidiLoader = new CacheMidiLoader();
        cacheMidiLoader.init(config.cachePathOverride());

        initializeSoundfont();

        // Apply saved beat offset
        if (midiTickPlayer != null) {
            midiTickPlayer.setBeatOffset(getBeatOffsetMs());
        }

        // Pre-load jukebox folder if jukebox mode is already on
        if (isJukeboxEnabled()) {
            customMidiPlayer.loadFolder(getMidiFolder());
        }

        overlayManager.add(overlay);

        keyManager.registerKeyListener(playPauseListener);
        keyManager.registerKeyListener(nextListener);
        keyManager.registerKeyListener(prevListener);
        keyManager.registerKeyListener(stopListener);

        // ── Sidebar panel ────────────────────────────────────────────────────
        panel = new TickSyncMusicPanel(this, configManager);

        BufferedImage icon;
        try {
            icon = ImageUtil.loadImageResource(getClass(), "/sidebar_icon.png");
        } catch (Exception e) {
            // Fallback: plain orange 18x18 square
            icon = new BufferedImage(18, 18, BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = icon.createGraphics();
            try {
                g.setColor(new Color(200, 150, 0));
                g.fillRect(0, 0, 18, 18);
            } finally {
                g.dispose();
            }
        }

        navButton = NavigationButton.builder()
                .tooltip("TickSync Music")
                .icon(icon)
                .priority(10)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);

        log.info("TickSync Music started (player initialized: {})", playerInitialized);
    }

    @Override
    protected void shutDown() throws Exception {
        log.info("TickSync Music shutting down…");

        keyManager.unregisterKeyListener(playPauseListener);
        keyManager.unregisterKeyListener(nextListener);
        keyManager.unregisterKeyListener(prevListener);
        keyManager.unregisterKeyListener(stopListener);

        if (navButton != null) {
            clientToolbar.removeNavigation(navButton);
            navButton = null;
        }
        panel = null;

        if (midiTickPlayer != null) {
            midiTickPlayer.shutdown();
        }

        if (cacheMidiLoader != null) {
            cacheMidiLoader.shutdown();
        }

        restoreGameMusicVolume();
        gameMusicMuted = false;
        overlayManager.remove(overlay);

        playerInitialized = false;
        jukeboxModeStarted = false;

        log.info("TickSync Music stopped");
    }

    // ── Event Subscribers ───────────────────────────────────────────────

    @Subscribe
    public void onGameTick(GameTick event) {

        if (!playerInitialized) {
            return;
        }

        // ── Volume management (client thread, every tick) ─────────────────────
        boolean shouldMute = isMuteGameMusic();
        if (shouldMute && !gameMusicMuted) {
            muteGameMusic();
            gameMusicMuted = true;
        } else if (!shouldMute && gameMusicMuted) {
            restoreGameMusicVolume();
            gameMusicMuted = false;
        }

        // ── Jukebox mode (takes full priority over game music) ────────────────
        if (isJukeboxEnabled()) {
            if (customMidiPlayer.hasTracks()) {
                // Not playing AND not paused AND no pending start → advance to next track
                boolean idle =
                        !midiTickPlayer.isPlaying() && !midiTickPlayer.hasPendingStart() && !midiTickPlayer.isPaused();
                if (idle) {
                    File nextFile;
                    if (!jukeboxModeStarted) {
                        nextFile = customMidiPlayer.getFirstTrack(getPlayMode());
                        jukeboxModeStarted = true;
                    } else {
                        nextFile = customMidiPlayer.getNextTrack(getPlayMode());
                    }
                    if (nextFile != null) {
                        loadAndPlayMidiFile(nextFile);
                    }
                }
            }
            midiTickPlayer.onTick();
            midiTickPlayer.setVolume(getVolume() / 100f);
            pushPanelUpdate();
            return;
        }

        // ── OSRS game music mode ──────────────────────────────────────────────
        if (!isGameMusicEnabled()) {
            pushPanelUpdate();
            return;
        }

        trackDetector.checkForTrackChange();

        midiTickPlayer.onTick();
        midiTickPlayer.setVolume(getVolume() / 100f);
        pushPanelUpdate();
    }

    /** Push a now-playing update to the sidebar panel on the EDT. */
    private void pushPanelUpdate() {
        if (panel == null || midiTickPlayer == null) {
            return;
        }
        final TickSyncMusicPanel currentPanel = panel;
        final String trackName = getCurrentTrackName();

        final boolean playing = midiTickPlayer.isPlaying();
        final boolean paused = midiTickPlayer.isPaused();

        final String modeTag = "[MIDI]";
        final String displayName = (trackName != null && !trackName.isEmpty()) ? trackName + " " + modeTag : trackName;

        final String status = playing ? "Playing" : (paused ? "Paused" : "Stopped");
        final float src = currentSourceBPM;
        final float tgt = midiTickPlayer.getCurrentTargetBPM();
        final long drift = midiTickPlayer.getLastDriftMicros() / 1000L;
        SwingUtilities.invokeLater(() -> {
            if (currentPanel != null) {
                currentPanel.updateNowPlaying(displayName, status, src, tgt, drift);
            }
        });
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            if (trackDetector != null) {
                trackDetector.resetLoginDelay();
            }

            jukeboxModeStarted = false;
            log.info("TickSync: LOGGED_IN — starting track detection in {} ticks", TrackDetector.LOGIN_DELAY_TICKS);
        } else if (event.getGameState() == GameState.LOGIN_SCREEN) {
            if (midiTickPlayer != null) {
                midiTickPlayer.stop();
            }
            restoreGameMusicVolume();
            gameMusicMuted = false;
            jukeboxModeStarted = false;
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!"ticksyncmusic".equals(event.getGroup())) {
            return;
        }

        switch (event.getKey()) {
            case "volume":
                // Volume changed via panel slider — update player immediately
                if (midiTickPlayer != null) {
                    midiTickPlayer.setVolume(getVolume() / 100f);
                }
                break;

            case "muteGameMusic":
                // Handled on next tick (client thread context needed for setMusicVolume)
                break;

            case "gameMusicEnabled":
                if (!playerInitialized || isJukeboxEnabled()) {
                    break;
                }
                if (!isGameMusicEnabled()) {
                    if (midiTickPlayer != null) {
                        midiTickPlayer.stop();
                        log.info("TickSync: game music disabled");
                    }
                } else {
                    if (trackDetector != null) {
                        trackDetector.resetDetection();
                        log.info("TickSync: game music re-enabled");
                    }
                }
                break;

            case "jukeboxEnabled":
                if (!playerInitialized) {
                    break;
                }
                midiTickPlayer.stop();
                jukeboxModeStarted = false;
                if (isJukeboxEnabled()) {
                    log.info("TickSync: jukebox enabled — game music sync paused");
                    customMidiPlayer.loadFolder(getMidiFolder());
                } else {
                    log.info("TickSync: jukebox disabled — resuming OSRS track detection");
                    if (trackDetector != null) {
                        trackDetector.resetDetection();
                    }
                }
                break;

            case "customMidiFolder":
                if (!isJukeboxEnabled() || !playerInitialized) {
                    break;
                }
                log.info("TickSync: MIDI folder changed — reloading");
                midiTickPlayer.stop();
                jukeboxModeStarted = false;
                customMidiPlayer.loadFolder(getMidiFolder());
                // Notify panel to refresh track list
                if (panel != null) {
                    final String folder = getMidiFolder();
                    SwingUtilities.invokeLater(() -> panel.refreshTrackList(folder));
                }
                break;

            case "playMode":
                if (isJukeboxEnabled() && playerInitialized) {
                    boolean loop = (getPlayMode() == CustomPlayMode.REPEAT_ONE);
                    midiTickPlayer.setLooping(loop);
                    log.info("TickSync: playMode changed (looping={})", loop);
                }
                break;

            case "snapMode":
                if (!playerInitialized || trackDetector == null) {
                    break;
                }
                if (panel != null) {
                    SwingUtilities.invokeLater(() -> panel.syncSoundSettings());
                }
                if (isJukeboxEnabled()) {
                    File current = customMidiPlayer.getCurrentTrack();
                    if (current != null) {
                        log.info(
                                "TickSync: snapMode changed — reloading jukebox track [{}]",
                                customMidiPlayer.getCurrentTrackName());
                        loadAndPlayMidiFile(current);
                    }
                    break;
                }
                String currentTrack = trackDetector.getCurrentTrackName();
                if (currentTrack != null && !currentTrack.isEmpty()) {
                    String filename = trackDetector.getMidiFilename(currentTrack);
                    if (filename != null) {
                        log.info("TickSync: snapMode changed — reloading [{}]", currentTrack);
                        loadAndPlayMidi(filename);
                    }
                }
                break;

            case "soundfontMode":
            case "customSoundfontPath":
                if (!playerInitialized) {
                    break;
                }
                if (panel != null) {
                    SwingUtilities.invokeLater(() -> panel.syncSoundSettings());
                }
                SoundfontMode mode = config.soundfontMode();
                if ("customSoundfontPath".equals(event.getKey()) && mode != SoundfontMode.CUSTOM) {
                    break;
                }
                log.info("TickSync: soundfont changed to {} — reloading", mode);
                midiTickPlayer.stop();
                jukeboxModeStarted = false;
                try {
                    midiTickPlayer.switchSoundfont(mode, config.customSoundfontPath());
                } catch (Exception e) {
                    log.error("Failed to switch soundfont to {}", mode, e);
                }
                if (isJukeboxEnabled()) {
                    File cur = customMidiPlayer.getCurrentTrack();
                    if (cur != null) {
                        loadAndPlayMidiFile(cur);
                    }
                } else if (trackDetector != null) {
                    trackDetector.resetDetection();
                }
                break;

            case "beatOffsetMs":
                if (midiTickPlayer != null) {
                    int ms = getBeatOffsetMs();
                    midiTickPlayer.setBeatOffset(ms);
                    log.info("TickSync: beat offset changed to {}ms — drift correction forced on next tick", ms);
                }
                break;

            case "cachePathOverride":
                log.info("TickSync: cache path changed — reinitialising cache loader");
                if (midiTickPlayer != null) {
                    midiTickPlayer.stop();
                }
                if (cacheMidiLoader != null) {
                    cacheMidiLoader.shutdown();
                    cacheMidiLoader.init(config.cachePathOverride());
                }
                if (trackDetector != null) {
                    trackDetector.resetDetection();
                }
                break;

            case "normalizeVolume":
            case "compressDynamics":
                if (!playerInitialized) {
                    break;
                }
                log.info("TickSync: {} changed — reloading current track", event.getKey());
                if (isJukeboxEnabled()) {
                    File curFile = customMidiPlayer.getCurrentTrack();
                    if (curFile != null) {
                        loadAndPlayMidiFile(curFile);
                    }
                } else if (trackDetector != null) {
                    String curTrack = trackDetector.getCurrentTrackName();
                    if (curTrack != null && !curTrack.isEmpty()) {
                        String fn = trackDetector.getMidiFilename(curTrack);
                        if (fn != null) {
                            loadAndPlayMidi(fn);
                        }
                    }
                }
                break;
            default:
                // Config key not handled by this plugin — ignore.
                break;
        }
    }

    // ── Internals ───────────────────────────────────────────────────────

    /**
     * Download (if absent) and load the OSRS soundfont from the local cache,
     * then immediately switch to the user's configured soundfont mode.
     * Falls back to Java's default GM soundbank if the download fails.
     */
    private void initializeSoundfont() {
        File sf2File = SoundfontDownloader.ensureSoundfont();
        try {
            midiTickPlayer.init(sf2File);
            if (sf2File != null) {
                log.info("OSRS soundfont loaded from {}",
                        sf2File.getAbsolutePath());
            }
            playerInitialized = true;
        } catch (Exception e) {
            log.error("Failed to initialize MIDI player", e);
            playerInitialized = false;
            return;
        }

        // Apply the globally configured soundfont mode (applies to all music sources)
        SoundfontMode mode = config.soundfontMode();
        if (mode != SoundfontMode.OSRS) {
            try {
                midiTickPlayer.switchSoundfont(mode, config.customSoundfontPath());
            } catch (Exception e) {
                log.error("Failed to apply soundfont mode {} at startup", mode, e);
            }
        }
    }

    /**
     * Callback from TrackDetector when the in-game music track changes.
     */
    private void onTrackChanged(String newTrackName) {
        if (!playerInitialized) {
            return;
        }
        onTrackChangedMidi(newTrackName);
    }

    /** MIDI-mode track-change handler. */
    private void onTrackChangedMidi(String newTrackName) {
        String filename = trackDetector.getMidiFilename(newTrackName);
        if (filename == null) {
            log.info("TickSync: no MIDI for track [{}]", newTrackName);
            return;
        }

        log.info("TickSync: playing [{}] from [{}]", newTrackName, filename);
        loadAndPlayMidi(filename);
    }

    /**
     * Load a music track from the OSRS cache, run it through TempoQuantizer, and queue for playback.
     * Playback starts on the next GameTick (aligned to the tick grid).
     *
     * @param filename the MIDI filename from trackMappings.json (e.g. "556.mid" or "556")
     *                 — the numeric portion is parsed as the cache archive ID.
     */
    private void loadAndPlayMidi(String filename) {
        // Parse cache ID from filename string (e.g. "556.mid" → 556)
        int cacheId;
        try {
            String numStr = filename.endsWith(".mid") ? filename.substring(0, filename.length() - 4) : filename;
            cacheId = Integer.parseInt(numStr.trim());
        } catch (NumberFormatException e) {
            log.warn("TickSync: cannot parse cache ID from '{}' — skipping", filename);
            return;
        }

        // 1. Load Sequence directly from the OSRS cache
        Sequence rawSequence = cacheMidiLoader.loadTrack(cacheId);
        if (rawSequence == null) {
            log.warn("TickSync: track {} not found in cache — keeping current playback", cacheId);
            return;
        }

        try {
            // 2. Rewrite tempo events; remap ch9→ch15 only when OSRS soundfont is active
            boolean remapDrums = (config.soundfontMode() == SoundfontMode.OSRS);
            currentSourceBPM = TempoQuantizer.getFirstTempoBPM(rawSequence);
            Sequence quantizedSequence = TempoQuantizer.process(rawSequence, config.snapMode(), remapDrums);

            // 3. Velocity normalization
            if (isNormalizeVolume()) {
                quantizedSequence = VelocityNormalizer.normalize(quantizedSequence, 80);
            }

            // 4. Dynamics compression
            if (isCompressDynamics()) {
                quantizedSequence = VelocityNormalizer.compress(quantizedSequence, 3.0f, 90);
            }

            // 5. Read the (now quantized) target BPM for display / sync
            float targetBPM = TempoQuantizer.getFirstTempoBPM(quantizedSequence);

            log.info("Cache track loaded: {} (id={}) — quantized target BPM: {}", filename, cacheId, targetBPM);

            // 6. Stop any existing playback before starting new sequence (no layering)
            midiTickPlayer.stop();

            // 7. Queue for playback (starts on next onTick)
            midiTickPlayer.loadSequence(quantizedSequence, targetBPM);
        } catch (Exception e) {
            log.error("Failed to process cache track: {}", filename, e);
        }
    }

    /**
     * Load a MIDI file from the filesystem (custom mode), quantize it, and queue for playback.
     * Channel-9 remap is applied only when the OSRS soundfont is active.
     * Skips the file (with a warning) if it can't be parsed as valid MIDI.
     */
    private void loadAndPlayMidiFile(File file) {
        if (file == null || !file.exists()) {
            log.warn("TickSync: custom MIDI file not found: {}", file);
            return;
        }

        try (InputStream midiStream = new FileInputStream(file)) {
            Sequence rawSequence = MidiSystem.getSequence(midiStream);

            // Remap ch9 only when using OSRS soundfont (Gervill drum-lock workaround)
            boolean remapDrums = (config.soundfontMode() == SoundfontMode.OSRS);
            currentSourceBPM = TempoQuantizer.getFirstTempoBPM(rawSequence);
            Sequence quantizedSequence = TempoQuantizer.process(rawSequence, config.snapMode(), remapDrums);

            // Velocity normalization
            if (isNormalizeVolume()) {
                quantizedSequence = VelocityNormalizer.normalize(quantizedSequence, 80);
            }

            // Dynamics compression
            if (isCompressDynamics()) {
                quantizedSequence = VelocityNormalizer.compress(quantizedSequence, 3.0f, 90);
            }

            float targetBPM = TempoQuantizer.getFirstTempoBPM(quantizedSequence);
            log.info(
                    "TickSync [Jukebox]: playing [{}] — BPM: {} remapDrums: {}", file.getName(), targetBPM, remapDrums);

            // Set looping based on play mode BEFORE loading the sequence
            midiTickPlayer.setLooping(getPlayMode() == CustomPlayMode.REPEAT_ONE);

            midiTickPlayer.stop();
            midiTickPlayer.loadSequence(quantizedSequence, targetBPM);
        } catch (Exception e) {
            log.warn("TickSync [Jukebox]: failed to load [{}] — skipping. Error: {}", file.getName(), e.getMessage());
            // Skip this file — on the next tick the plugin will try getNextTrack()
            jukeboxModeStarted = true; // mark started so we call getNextTrack not getFirstTrack
        }
    }

    // ── Transport helpers (called by hotkey listeners and sidebar panel) ────────

    /**
     * Toggle play/pause:
     * - Playing → pause (retain position)
     * - Paused  → resume
     * - Stopped + jukebox enabled → start first track
     */
    public void togglePlayPause() {
        if (!playerInitialized || midiTickPlayer == null) {
            return;
        }
        if (midiTickPlayer.isPlaying()) {
            midiTickPlayer.pause();
        } else if (midiTickPlayer.isPaused()) {
            midiTickPlayer.resume();
        } else if (isJukeboxEnabled() && customMidiPlayer != null && customMidiPlayer.hasTracks()) {
            File track = customMidiPlayer.getFirstTrack(getPlayMode());
            if (track != null) {
                jukeboxModeStarted = true;
                loadAndPlayMidiFile(track);
            }
        }
    }

    /** Jukebox only: skip to the next track according to current play mode. */
    public void nextTrack() {
        if (!playerInitialized || midiTickPlayer == null) {
            return;
        }
        if (!isJukeboxEnabled() || customMidiPlayer == null || !customMidiPlayer.hasTracks()) {
            return;
        }
        midiTickPlayer.stop();
        File next = customMidiPlayer.getNextTrack(getPlayMode());
        if (next != null) {
            jukeboxModeStarted = true;
            loadAndPlayMidiFile(next);
        }
    }

    /** Jukebox only: go back to the previous track. */
    public void prevTrack() {
        if (!playerInitialized || midiTickPlayer == null) {
            return;
        }
        if (!isJukeboxEnabled() || customMidiPlayer == null || !customMidiPlayer.hasTracks()) {
            return;
        }
        midiTickPlayer.stop();
        File prev = customMidiPlayer.getPrevTrack(getPlayMode());
        if (prev != null) {
            jukeboxModeStarted = true;
            loadAndPlayMidiFile(prev);
        }
    }

    /** Stop all playback and reset position to 0. */
    public void stopPlayback() {
        if (midiTickPlayer != null) {
            midiTickPlayer.stop();
        }
    }

    /**
     * Jukebox only: play the track at a specific index in the loaded track list.
     * Called from the sidebar panel's track list click handler.
     */
    public void playTrackAtIndex(int index) {
        if (!playerInitialized || customMidiPlayer == null || !isJukeboxEnabled()) {
            return;
        }
        File track = customMidiPlayer.seekToIndex(index);
        if (track != null) {
            jukeboxModeStarted = true;
            loadAndPlayMidiFile(track);
        }
    }

    /** @return the current track index in the jukebox list (for panel highlight). */
    public int getCurrentTrackIndex() {
        return customMidiPlayer != null ? customMidiPlayer.getCurrentIndex() : -1;
    }

    // ── Volume Management ───────────────────────────────────────────────

    private void muteGameMusic() {
        try {
            if (originalMusicVolume < 0) {
                originalMusicVolume = client.getMusicVolume();
            }
            client.setMusicVolume(0);
        } catch (Exception e) {
            log.debug("Could not mute game music: {}", e.getMessage());
        }
    }

    private void restoreGameMusicVolume() {
        try {
            if (originalMusicVolume >= 0) {
                client.setMusicVolume(originalMusicVolume);
                originalMusicVolume = -1;
            }
        } catch (Exception e) {
            log.debug("Could not restore game music volume: {}", e.getMessage());
        }
    }

    // ── Public Accessors (used by Overlay and Panel) ────────────────────

    public String getCurrentTrackName() {
        if (isJukeboxEnabled() && customMidiPlayer != null) {
            return customMidiPlayer.getCurrentTrackName();
        }
        return trackDetector != null ? trackDetector.getCurrentTrackName() : "";
    }

    /** @return true when jukebox mode is enabled and has tracks loaded */
    public boolean isCustomModeActive() {
        return isJukeboxEnabled() && customMidiPlayer != null && customMidiPlayer.hasTracks();
    }

    // ── ConfigManager-backed state (interactive values owned by the sidebar) ─

    private static final String CFG_GROUP = "ticksyncmusic";

    /** @return current playback volume in the range [0, 100]; defaults to 50. */
    public int getVolume() {
        Integer v = configManager.getConfiguration(CFG_GROUP, "volume", Integer.class);
        return (v != null) ? v : 50;
    }

    /** @return {@code true} if the in-game music volume should be forced to 0 while this plugin plays. */
    public boolean isMuteGameMusic() {
        Boolean b = configManager.getConfiguration(CFG_GROUP, "muteGameMusic", Boolean.class);
        return (b != null) ? b : true;
    }

    /**
     * @return {@code true} if velocity normalization is enabled.
     *         Reads directly from the config interface for consistency with other config-backed flags.
     */
    public boolean isNormalizeVolume() {
        return config.normalizeVolume();
    }

    /**
     * @return {@code true} if dynamics compression is enabled.
     *         Reads directly from the config interface for consistency with other config-backed flags.
     */
    public boolean isCompressDynamics() {
        return config.compressDynamics();
    }

    /** @return beat-offset delay in milliseconds (0 = no offset); clamped to ≥ 0. */
    public int getBeatOffsetMs() {
        Integer v = configManager.getConfiguration(CFG_GROUP, "beatOffsetMs", Integer.class);
        return (v != null) ? Math.max(0, v) : 0;
    }

    /** @return {@code true} if OSRS game-music sync mode is active. */
    public boolean isGameMusicEnabled() {
        Boolean b = configManager.getConfiguration(CFG_GROUP, "gameMusicEnabled", Boolean.class);
        return (b != null) ? b : true;
    }

    /** @return {@code true} if Jukebox mode is active (plays from the custom MIDI folder). */
    public boolean isJukeboxEnabled() {
        Boolean b = configManager.getConfiguration(CFG_GROUP, "jukeboxEnabled", Boolean.class);
        return (b != null) ? b : false;
    }

    /** @return the configured custom MIDI folder path, or an empty string if not set. */
    public String getMidiFolder() {
        String s = configManager.getConfiguration(CFG_GROUP, "customMidiFolder");
        return (s != null) ? s : "";
    }

    /** @return the current Jukebox play mode; falls back to {@link CustomPlayMode#SEQUENTIAL}. */
    public CustomPlayMode getPlayMode() {
        String s = configManager.getConfiguration(CFG_GROUP, "playMode");
        if (s == null) {
            return CustomPlayMode.SEQUENTIAL;
        }
        try {
            return CustomPlayMode.valueOf(s);
        } catch (IllegalArgumentException e) {
            return CustomPlayMode.SEQUENTIAL;
        }
    }

    /** @return the currently configured soundfont mode. */
    public SoundfontMode getSoundfontMode() {
        return config.soundfontMode();
    }

    /** @return the filesystem path to the user-supplied .sf2 file (empty when not set). */
    public String getCustomSoundfontPath() {
        return config.customSoundfontPath();
    }

    /** @return the current BPM snap strategy. */
    public SnapMode getSnapMode() {
        return config.snapMode();
    }

    /** Seek to an absolute position in microseconds. */
    public void seekToMicros(long micros) {
        if (midiTickPlayer != null) {
            midiTickPlayer.seekToMicros(micros);
        }
    }

    @Provides
    TickSyncMusicConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(TickSyncMusicConfig.class);
    }
}

package com.ticksync.music;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Optional debug overlay showing TickSync playback state.
 *
 * Displays:
 * - Current track name
 * - Playback status (Playing / Stopped / Not initialized)
 * - Target BPM
 * - Ticks since playback started
 * - Current drift in milliseconds
 *
 * Toggle via the "Show Debug Overlay" config option.
 */
public class TickSyncOverlay extends Overlay {
    private final TickSyncMusicPlugin plugin;
    private final TickSyncMusicConfig config;
    private final PanelComponent panelComponent = new PanelComponent();

    @Inject
    public TickSyncOverlay(TickSyncMusicPlugin plugin, TickSyncMusicConfig config) {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.showOverlay()) {
            return null;
        }

        panelComponent.getChildren().clear();
        panelComponent.setPreferredSize(new Dimension(200, 0));

        // Title with mode indicator
        boolean customActive = plugin.isCustomModeActive();
        panelComponent
                .getChildren()
                .add(TitleComponent.builder()
                        .text("TickSync Music")
                        .color(Color.CYAN)
                        .build());

        panelComponent
                .getChildren()
                .add(LineComponent.builder()
                        .left("Mode:")
                        .right(customActive ? "[Custom]" : "[OSRS]")
                        .rightColor(customActive ? Color.YELLOW : Color.CYAN)
                        .build());

        // Current track
        String trackName = plugin.getCurrentTrackName();
        panelComponent
                .getChildren()
                .add(LineComponent.builder()
                        .left("Track:")
                        .right(trackName != null && !trackName.isEmpty() ? trackName : "None")
                        .build());

        // Player state
        MidiTickPlayer player = plugin.getMidiTickPlayer();
        if (player != null && player.isInitialized()) {
            boolean playing = player.isPlaying();
            boolean paused = player.isPaused();

            String statusText = playing ? "Playing" : (paused ? "Paused" : "Stopped");
            Color statusColor = playing ? Color.GREEN : (paused ? Color.YELLOW : Color.RED);

            panelComponent
                    .getChildren()
                    .add(LineComponent.builder()
                            .left("Status:")
                            .right(statusText)
                            .rightColor(statusColor)
                            .build());

            panelComponent
                    .getChildren()
                    .add(LineComponent.builder()
                            .left("Target BPM:")
                            .right(String.format("%.0f", player.getCurrentTargetBPM()))
                            .build());

            panelComponent
                    .getChildren()
                    .add(LineComponent.builder()
                            .left("Ticks:")
                            .right(String.valueOf(player.getTicksSinceStart()))
                            .build());

            long driftMs = player.getLastDriftMicros() / 1000;
            panelComponent
                    .getChildren()
                    .add(LineComponent.builder()
                            .left("Drift:")
                            .right(driftMs + " ms")
                            .rightColor(Math.abs(driftMs) > 50 ? Color.RED : Color.GREEN)
                            .build());

            int offsetMs = player.getBeatOffsetMs();
            panelComponent
                    .getChildren()
                    .add(LineComponent.builder()
                            .left("Offset:")
                            .right(offsetMs + " ms")
                            .rightColor(offsetMs > 0 ? Color.YELLOW : Color.WHITE)
                            .build());
        } else {
            panelComponent
                    .getChildren()
                    .add(LineComponent.builder()
                            .left("Status:")
                            .right("Not initialized")
                            .rightColor(Color.YELLOW)
                            .build());
        }

        return panelComponent.render(graphics);
    }
}

package com.ticksync.music;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

/**
 * Detects which music track is currently playing in OSRS.
 *
 * Primary approach: reads the track name from the music tab widget.
 * The music tab (interface group 239) shows the currently playing track.
 *
 * Maintains a mapping of known track names → MIDI resource filenames
 * so the plugin can load the right MIDI file for playback.
 */
@Slf4j
public class TrackDetector {
    /**
     * Widget group ID for the music player interface.
     * This is the music tab that players open to see their track list.
     */
    private static final int MUSIC_INTERFACE_GROUP = 239;

    /**
     * Child widget index for the currently-playing track name.
     *
     * NOTE: This value may need adjustment based on the OSRS client version.
     * If track detection isn't working, inspect the widget tree with RuneLite's
     * Developer Tools → Widget Inspector to find the correct child ID.
     * Common candidates: 3, 4, 6, 7.
     */
    // Confirmed via widget scan: [239,3]="Playing:" label, [239,4]=track name, [239,5]=unlock count
    private static final int MUSIC_TRACK_NAME_CHILD = 4;

    /** Fallback candidate widget IDs if primary doesn't work. */
    private static final int[] FALLBACK_CHILD_IDS = {3, 6, 7};

    /**
     * Widget texts that are UI labels, not real track names.
     * "Playing:" is the static label shown before the track name populates
     * on first login. Ignore any of these values.
     */
    private static final Set<String> INVALID_TRACK_NAMES =
            new HashSet<>(Arrays.asList("Playing:", "Playing", "Music", "-"));

    /**
     * Number of game ticks to wait after login before attempting track detection.
     * The music widget takes a few ticks to populate with the real track name.
     * At 600 ms/tick, 5 ticks = 3 seconds — enough for the widget to settle.
     */
    static final int LOGIN_DELAY_TICKS = 5;

    /**
     * Number of ticks between periodic debug heartbeat log lines.
     * Used only at DEBUG level; not visible in production unless debug logging is enabled.
     */
    private static final int TICK_LOG_INTERVAL = 10;

    /** Counts down from LOGIN_DELAY_TICKS after each login. Detection is skipped while > 0. */
    private int loginDelayTicksRemaining = 0;

    /** Total ticks since construction — used for periodic debug log messages. */
    private int tickCounter = 0;

    /**
     * Set true after the login delay expires and we log the full widget scan once.
     * Reset on each new login so we always get a fresh scan after delay.
     */
    private boolean hasLoggedFirstScan = false;

    private final Client client;

    /** The track name most recently reported by the in-game music widget. */
    @Getter
    private String currentTrackName = "";

    private Consumer<String> onTrackChange;

    /**
     * Mapping: in-game track name → MIDI filename (e.g. "556.mid").
     * Loaded at construction time from trackMappings.json on the classpath.
     */
    private final Map<String, String> trackToMidi = new HashMap<>();

    /**
     * Construct a TrackDetector for the given client.
     * Loads {@code trackMappings.json} from the classpath immediately.
     *
     * @param client the RuneLite API client
     */
    public TrackDetector(Client client) {
        this.client = client;
        loadTrackMappings();
    }

    /**
     * Load track name → MIDI filename mappings from trackMappings.json.
     *
     * The file is a flat JSON object:  { "Track Name": "NNN.mid", ... }
     * Parsed with a simple regex — no external JSON library needed.
     */
    private void loadTrackMappings() {
        try (InputStream is = getClass().getClassLoader().getResourceAsStream("trackMappings.json")) {
            if (is == null) {
                log.warn("TrackDetector: trackMappings.json not found on classpath — no mappings loaded");
                return;
            }

            StringBuilder sb = new StringBuilder();
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    sb.append(line);
                }
            }

            // Match every "key": "value" pair in the flat JSON
            Pattern pattern = Pattern.compile("\"([^\"]+)\"\\s*:\\s*\"([^\"]+)\"");
            Matcher matcher = pattern.matcher(sb.toString());
            int count = 0;
            while (matcher.find()) {
                trackToMidi.put(matcher.group(1), matcher.group(2));
                count++;
            }
            log.info("TrackDetector: loaded {} track mappings from trackMappings.json", count);
        } catch (Exception e) {
            log.error("TrackDetector: failed to load trackMappings.json", e);
        }
    }

    /**
     * Set a callback that fires whenever the detected track changes.
     * The callback receives the new track name.
     *
     * @param callback consumer that receives the new track name
     */
    public void setOnTrackChange(Consumer<String> callback) {
        this.onTrackChange = callback;
    }

    /**
     * Called every GameTick to poll the music widget for the current track.
     * If the track changed, fires the onTrackChange callback.
     */
    public void checkForTrackChange() {
        tickCounter++;

        // Per-tick DEBUG: log the raw widget state
        Widget primaryWidget = client.getWidget(MUSIC_INTERFACE_GROUP, MUSIC_TRACK_NAME_CHILD);
        String rawWidgetText;
        if (primaryWidget == null) {
            rawWidgetText = "null";
        } else {
            String t = primaryWidget.getText();
            rawWidgetText = "text='" + (t != null ? t : "(null)") + "'" + " hidden=" + primaryWidget.isHidden();
        }
        log.debug(
                "TrackDetector tick #{}: widget({},{})={}",
                tickCounter,
                MUSIC_INTERFACE_GROUP,
                MUSIC_TRACK_NAME_CHILD,
                rawWidgetText);

        // Periodic debug heartbeat — helps confirm the listener is firing
        if (tickCounter % TICK_LOG_INTERVAL == 0) {
            log.debug(
                    "TrackDetector: tick #{} — loginDelay={} currentTrack='{}'",
                    tickCounter,
                    loginDelayTicksRemaining,
                    currentTrackName);
        }

        // Post-login delay: wait for the widget to fully populate
        if (loginDelayTicksRemaining > 0) {
            loginDelayTicksRemaining--;
            log.debug("TrackDetector: waiting for widget to settle ({} ticks remaining)", loginDelayTicksRemaining);
            return;
        }

        // First tick after delay: do a one-time full widget scan
        if (!hasLoggedFirstScan) {
            hasLoggedFirstScan = true;
            scanAllMusicWidgetChildren();
        }

        String newTrackName = detectCurrentTrack();

        // Reject null, empty, or known UI-label strings
        if (newTrackName == null || newTrackName.isEmpty() || INVALID_TRACK_NAMES.contains(newTrackName)) {
            if (newTrackName != null && !newTrackName.isEmpty()) {
                log.debug("TrackDetector: ignoring UI label '{}' — not a real track name", newTrackName);
            }
            return;
        }

        if (!newTrackName.equals(currentTrackName)) {
            String oldTrack = currentTrackName;
            currentTrackName = newTrackName;
            log.info("Track changed: '{}' → '{}'", oldTrack, newTrackName);

            if (onTrackChange != null) {
                onTrackChange.accept(currentTrackName);
            }
        }
    }

    /**
     * Call this when the player logs in to start the post-login delay.
     * Prevents reading the "Playing:" UI label before the widget populates.
     */
    public void resetLoginDelay() {
        loginDelayTicksRemaining = LOGIN_DELAY_TICKS;
        hasLoggedFirstScan = false;
        log.info("TrackDetector: login detected — waiting {} ticks for widget to settle", LOGIN_DELAY_TICKS);
    }

    /**
     * Try to read the currently playing track name from the music widget.
     * Returns null if the widget isn't loaded (e.g., music tab not open).
     * Tries multiple widget child IDs to work around version changes.
     *
     * @return the track name text, or {@code null} if unavailable
     */
    private String detectCurrentTrack() {
        try {
            // Try primary widget ID first
            String text = readMusicWidgetText(MUSIC_TRACK_NAME_CHILD);
            if (text != null && !text.isEmpty()) {
                return text;
            }

            // Try fallback IDs if primary fails (silently, no log spam)
            for (int childId : FALLBACK_CHILD_IDS) {
                text = readMusicWidgetText(childId);
                if (text != null && !text.isEmpty()) {
                    log.info("Found music track at fallback widget child ID: {}", childId);
                    return text;
                }
            }

            // Widget group not found at all
            log.debug("Music widget group {} not accessible", MUSIC_INTERFACE_GROUP);
        } catch (Exception e) {
            log.debug("Could not read music widget: {}", e.getMessage());
        }
        return null;
    }

    /**
     * Helper: read text from a music widget child by ID.
     * Returns {@code null} if the widget is null, hidden, or has empty text.
     *
     * @param childId the child widget index within {@value #MUSIC_INTERFACE_GROUP}
     * @return stripped widget text, or {@code null}
     */
    private String readMusicWidgetText(int childId) {
        try {
            Widget musicWidget = client.getWidget(MUSIC_INTERFACE_GROUP, childId);
            if (musicWidget != null) {
                String text = musicWidget.getText();
                if (text != null && !text.isEmpty()) {
                    // Strip HTML formatting tags that RuneLite widgets may include
                    text = text.replaceAll("<[^>]*>", "").trim();
                    if (!text.isEmpty()) {
                        return text;
                    }
                }
            }
        } catch (Exception e) {
            log.debug("readMusicWidgetText({}): {}", childId, e.getMessage());
        }
        return null;
    }

    /**
     * Returns {@code true} if the given text is a known UI label, empty, or null —
     * i.e. it is <em>not</em> a real in-game track name.
     * Package-private for unit testing.
     */
    static boolean isInvalidTrackName(String name) {
        return name == null || name.isEmpty() || INVALID_TRACK_NAMES.contains(name);
    }

    /**
     * Reset the remembered track name so the next checkForTrackChange() call
     * treats the current track as "new" and fires onTrackChange.
     * Used when the plugin is re-enabled after being turned off.
     */
    public void resetDetection() {
        currentTrackName = "";
        log.info("TrackDetector: detection reset — will re-fire current track on next tick");
    }

    /**
     * Get the MIDI filename for a given track name (e.g. "556.mid").
     *
     * @param trackName the in-game track name
     * @return the bare filename, or {@code null} if the track has no mapping
     */
    public String getMidiFilename(String trackName) {
        return trackToMidi.get(trackName);
    }

    /**
     * One-time full scan of the music interface widget tree.
     * Fired on the first tick after the login delay expires.
     *
     * Checks two separate child sources because OSRS widgets use both:
     *   1. Fixed children  — client.getWidget(group, index)  — set at interface definition time
     *   2. Dynamic children — widget.getChildren()           — added at runtime by client scripts
     *
     * The "now playing" track text is typically a dynamic child of the container at child 0,
     * NOT a fixed child — this is the most common reason group-239/child-N reads fail.
     */
    private void scanAllMusicWidgetChildren() {
        log.info("=== TrackDetector: WIDGET SCAN — group {} ===", MUSIC_INTERFACE_GROUP);

        // ── Part 1: Fixed children (client.getWidget(group, 0..20)) ──
        log.info("  [fixed children 0..20]");
        for (int childId = 0; childId <= 20; childId++) {
            try {
                Widget w = client.getWidget(MUSIC_INTERFACE_GROUP, childId);
                if (w != null) {
                    String text = w.getText();
                    log.info(
                            "    [{},{}] text='{}' hidden={} type={}",
                            MUSIC_INTERFACE_GROUP,
                            childId,
                            text != null ? text : "(null)",
                            w.isHidden(),
                            w.getType());
                } else {
                    log.info("    [{},{}] = null", MUSIC_INTERFACE_GROUP, childId);
                }
            } catch (Exception e) {
                log.info("    [{},{}] threw: {}", MUSIC_INTERFACE_GROUP, childId, e.getMessage());
            }
        }

        // ── Part 2: Dynamic children of child-0 ──
        log.info("  [dynamic children of ({},0)]", MUSIC_INTERFACE_GROUP);
        try {
            Widget container = client.getWidget(MUSIC_INTERFACE_GROUP, 0);
            if (container == null) {
                log.info("    ({},0) is null — music tab may not be loaded yet", MUSIC_INTERFACE_GROUP);
            } else {
                Widget[] dynChildren = container.getChildren();
                if (dynChildren == null || dynChildren.length == 0) {
                    log.info("    ({},0).getChildren() is null/empty — no dynamic children", MUSIC_INTERFACE_GROUP);
                } else {
                    log.info("    ({},0) has {} dynamic children", MUSIC_INTERFACE_GROUP, dynChildren.length);
                    for (int i = 0; i < dynChildren.length; i++) {
                        Widget child = dynChildren[i];
                        if (child != null) {
                            String text = child.getText();
                            log.info(
                                    "      [dyn {}] text='{}' hidden={} type={}",
                                    i,
                                    text != null ? text.substring(0, Math.min(60, text.length())) : "(null)",
                                    child.isHidden(),
                                    child.getType());
                        }
                    }
                }
            }
        } catch (Exception e) {
            log.info("    dynamic children scan threw: {}", e.getMessage());
        }

        log.info("=== TrackDetector: WIDGET SCAN END ===");
    }
}

package com.ticksync.music;

import javax.sound.midi.InvalidMidiDataException;
import javax.sound.midi.MidiEvent;
import javax.sound.midi.MidiMessage;
import javax.sound.midi.Sequence;
import javax.sound.midi.ShortMessage;
import javax.sound.midi.Track;
import lombok.extern.slf4j.Slf4j;

/**
 * MIDI sequence preprocessing utility for velocity normalization and dynamics compression.
 *
 * Two operations, applied independently in the processing pipeline:
 *
 * 1. {@link #normalize} — scales all NOTE_ON velocities (and CC7 channel-volume messages)
 *    so the average velocity across the sequence reaches a target value.
 *    This evens out loudness between tracks that were authored at very different volumes.
 *
 * 2. {@link #compress} — applies soft compression above a velocity threshold and a subtle
 *    boost below a floor.  Useful for classical MIDI with wide dynamic swings (ppp → fff).
 *
 * Neither method mutates the original {@link Sequence}; both return a new copy, following
 * the same immutable-copy pattern used by {@link TempoQuantizer}.
 */
@Slf4j
public class VelocityNormalizer {
    /** Velocities below this floor are gently boosted by compress(). */
    private static final int VELOCITY_FLOOR = 30;

    // ── Public API ────────────────────────────────────────────────────────────

    /**
     * Scale all NOTE_ON velocities so the average across the sequence equals
     * {@code targetAvgVelocity}, then normalise CC7 (channel-volume) controllers
     * so their average approaches 100.
     *
     * <p>Velocity-0 NOTE_ON messages (note-off aliases) are left untouched.</p>
     *
     * @param original         source sequence (not mutated)
     * @param targetAvgVelocity desired mean velocity after scaling (typically 80)
     * @return new {@link Sequence} with adjusted velocities and CC7 values
     */
    public static Sequence normalize(Sequence original, int targetAvgVelocity) throws InvalidMidiDataException {
        // ── Pass 1: collect note-velocity statistics ──────────────────────────
        long velocitySum = 0;
        int noteCount = 0;

        for (Track track : original.getTracks()) {
            for (int i = 0; i < track.size(); i++) {
                MidiMessage msg = track.get(i).getMessage();
                if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;
                    // NOTE_ON with velocity > 0 only (velocity == 0 == note-off alias)
                    if (sm.getCommand() == ShortMessage.NOTE_ON && sm.getData2() > 0) {
                        velocitySum += sm.getData2();
                        noteCount++;
                    }
                }
            }
        }

        if (noteCount == 0) {
            log.info("VelocityNormalizer: no notes found — skipping normalization");
            return original;
        }

        double avgVelocity = (double) velocitySum / noteCount;
        double scaleFactor = (double) targetAvgVelocity / avgVelocity;
        log.info(
                "VelocityNormalizer: avg velocity {} → target {} (scale {})",
                String.format("%.1f", avgVelocity),
                targetAvgVelocity,
                String.format("%.3f", scaleFactor));

        // ── Pass 2: collect CC7 statistics ───────────────────────────────────
        long cc7Sum = 0;
        int cc7Count = 0;

        for (Track track : original.getTracks()) {
            for (int i = 0; i < track.size(); i++) {
                MidiMessage msg = track.get(i).getMessage();
                if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;
                    if (sm.getCommand() == ShortMessage.CONTROL_CHANGE && sm.getData1() == 7) {
                        cc7Sum += sm.getData2();
                        cc7Count++;
                    }
                }
            }
        }

        double cc7Scale = 1.0;
        if (cc7Count > 0) {
            double avgCC7 = (double) cc7Sum / cc7Count;
            cc7Scale = (avgCC7 > 0) ? 100.0 / avgCC7 : 1.0;
            log.info(
                    "VelocityNormalizer: avg CC7={} → target 100 (scale {})",
                    String.format("%.1f", avgCC7),
                    String.format("%.3f", cc7Scale));
        }

        // ── Pass 3: rebuild sequence with adjusted values ─────────────────────
        Sequence out = new Sequence(original.getDivisionType(), original.getResolution());
        final boolean adjustCC7 = (cc7Count > 0);
        final double finalCC7Scale = cc7Scale;

        for (Track track : original.getTracks()) {
            Track newTrack = out.createTrack();
            for (int i = 0; i < track.size(); i++) {
                MidiEvent event = track.get(i);
                MidiMessage msg = event.getMessage();

                if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;

                    // Scale NOTE_ON velocity
                    if (sm.getCommand() == ShortMessage.NOTE_ON && sm.getData2() > 0) {
                        int newVel = clamp((int) Math.round(sm.getData2() * scaleFactor), 1, 127);
                        ShortMessage fixed = new ShortMessage(sm.getCommand(), sm.getChannel(), sm.getData1(), newVel);
                        newTrack.add(new MidiEvent(fixed, event.getTick()));
                        continue;
                    }

                    // Scale CC7 channel volume
                    if (adjustCC7 && sm.getCommand() == ShortMessage.CONTROL_CHANGE && sm.getData1() == 7) {
                        int newCC7 = clamp((int) Math.round(sm.getData2() * finalCC7Scale), 1, 127);
                        ShortMessage fixed = new ShortMessage(sm.getCommand(), sm.getChannel(), sm.getData1(), newCC7);
                        newTrack.add(new MidiEvent(fixed, event.getTick()));
                        continue;
                    }
                }

                newTrack.add(event);
            }
        }
        return out;
    }

    /**
     * Apply soft dynamics compression to NOTE_ON velocities.
     *
     * <ul>
     *   <li>Velocities <b>above</b> {@code threshold}: the excess above the threshold
     *       is divided by {@code ratio}.
     *       E.g. ratio 2.0 with threshold 90: velocity 110 → 90 + (20 / 2) = 100.</li>
     *   <li>Velocities <b>below</b> {@link #VELOCITY_FLOOR}: a gentle 50 % boost is
     *       applied to the deficit, so very quiet notes remain audible.</li>
     * </ul>
     *
     * @param original  source sequence (not mutated)
     * @param ratio     compression ratio above threshold (2.0 = gentle, 4.0 = heavy)
     * @param threshold velocity above which compression kicks in (typically 90)
     * @return new {@link Sequence} with compressed dynamics
     */
    public static Sequence compress(Sequence original, float ratio, int threshold) throws InvalidMidiDataException {
        log.info("VelocityNormalizer: compressed dynamics (ratio={} threshold={})", ratio, threshold);

        Sequence out = new Sequence(original.getDivisionType(), original.getResolution());

        for (Track track : original.getTracks()) {
            Track newTrack = out.createTrack();
            for (int i = 0; i < track.size(); i++) {
                MidiEvent event = track.get(i);
                MidiMessage msg = event.getMessage();

                if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;
                    if (sm.getCommand() == ShortMessage.NOTE_ON && sm.getData2() > 0) {
                        int v = sm.getData2();
                        int newVel = v;

                        if (v > threshold) {
                            int excess = v - threshold;
                            newVel = clamp((int) Math.round(threshold + excess / (double) ratio), 1, 127);
                        } else if (v < VELOCITY_FLOOR) {
                            int boost = VELOCITY_FLOOR - v;
                            newVel = clamp((int) Math.round(v + boost * 0.5), 1, 127);
                        }

                        if (newVel != v) {
                            ShortMessage fixed =
                                    new ShortMessage(sm.getCommand(), sm.getChannel(), sm.getData1(), newVel);
                            newTrack.add(new MidiEvent(fixed, event.getTick()));
                            continue;
                        }
                    }
                }
                newTrack.add(event);
            }
        }
        return out;
    }

    // ── Utility ───────────────────────────────────────────────────────────────

    private static int clamp(int value, int min, int max) {
        return Math.max(min, Math.min(max, value));
    }
}

package com.ticksync.music;

import java.io.File;
import javax.sound.midi.MetaMessage;
import javax.sound.midi.MidiEvent;
import javax.sound.midi.MidiMessage;
import javax.sound.midi.MidiSystem;
import javax.sound.midi.Sequence;
import javax.sound.midi.ShortMessage;
import javax.sound.midi.Track;

/**
 * Standalone diagnostic: dumps every program change, bank select, and
 * tempo event from a MIDI file. Run this to see exactly what instrument
 * numbers and bank numbers the raw OSRS MIDI is requesting.
 *
 * Run via: ./gradlew run (or right-click → Run in IntelliJ)
 * Or just run main() directly.
 */
public class MidiDiagnostic {
    public static void main(String[] args) throws Exception {
        String midiPath = "src/main/resources/midi/556.mid";
        if (args.length > 0) midiPath = args[0];

        File f = new File(midiPath);
        if (!f.exists()) {
            System.err.println("File not found: " + f.getAbsolutePath());
            return;
        }

        Sequence seq = MidiSystem.getSequence(f);
        System.out.println("=== MIDI Diagnostic: " + f.getName() + " ===");
        System.out.printf(
                "Division type: %s  Resolution: %d ticks/beat%n",
                seq.getDivisionType() == Sequence.PPQ ? "PPQ" : "SMPTE", seq.getResolution());
        System.out.println("Tracks: " + seq.getTracks().length);
        System.out.println();

        int trackNum = 0;
        for (Track track : seq.getTracks()) {
            System.out.println("--- Track " + trackNum++ + " (" + track.size() + " events) ---");
            int[] bankMSB = new int[16];
            int[] bankLSB = new int[16];

            for (int i = 0; i < track.size(); i++) {
                MidiEvent evt = track.get(i);
                MidiMessage msg = evt.getMessage();
                long tick = evt.getTick();

                if (msg instanceof MetaMessage) {
                    MetaMessage meta = (MetaMessage) msg;
                    if (meta.getType() == 0x51) // SET_TEMPO
                    {
                        byte[] d = meta.getData();
                        int micros = ((d[0] & 0xFF) << 16) | ((d[1] & 0xFF) << 8) | (d[2] & 0xFF);
                        float bpm = 60_000_000f / micros;
                        System.out.printf("  tick %6d  TEMPO       %.2f BPM (%d µs/beat)%n", tick, bpm, micros);
                    }
                } else if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;
                    int ch = sm.getChannel();
                    int cmd = sm.getCommand();
                    int d1 = sm.getData1();
                    int d2 = sm.getData2();

                    if (cmd == ShortMessage.CONTROL_CHANGE) {
                        if (d1 == 0) // CC0 Bank MSB
                        {
                            bankMSB[ch] = d2;
                            System.out.printf("  tick %6d  ch%02d  CC0  Bank MSB = %d%n", tick, ch, d2);
                        } else if (d1 == 32) // CC32 Bank LSB
                        {
                            bankLSB[ch] = d2;
                            System.out.printf("  tick %6d  ch%02d  CC32 Bank LSB = %d%n", tick, ch, d2);
                        } else if (d1 == 7) // CC7 Volume
                        {
                            System.out.printf("  tick %6d  ch%02d  CC7  Volume = %d%n", tick, ch, d2);
                        } else if (d1 == 10) // CC10 Pan
                        {
                            System.out.printf("  tick %6d  ch%02d  CC10 Pan = %d%n", tick, ch, d2);
                        }
                    } else if (cmd == ShortMessage.PROGRAM_CHANGE) {
                        System.out.printf(
                                "  tick %6d  ch%02d  PROGRAM_CHANGE = %3d  (bank MSB=%d LSB=%d)%n",
                                tick, ch, d1, bankMSB[ch], bankLSB[ch]);
                    }
                }
            }
            System.out.println();
        }
        System.out.println("=== End Diagnostic ===");
    }
}

package com.ticksync.music;

import static org.junit.Assert.*;

import org.junit.Test;

/**
 * Unit tests for {@link MidiTickPlayer}.
 *
 * Full sequencer initialisation (synthesizer + sequencer open) is avoided in
 * unit tests because it requires an audio device that may not be present on
 * headless CI machines.  Instead, these tests exercise the pure arithmetic
 * used inside {@code onTick()} so the formulas can be validated independently
 * of the MIDI subsystem.
 */
public class MidiTickPlayerTest {
    /** Mirrors {@code MidiTickPlayer.TICK_DURATION_MICROS}. */
    private static final long TICK_DURATION_MICROS = 600_000L;

    // ── Drift expected-position formula ───────────────────────────────────────

    /**
     * The expected sequencer position at tick N with an optional beat-offset is:
     *
     * <pre>
     *   expected = (ticksSinceStart × TICK_DURATION_MICROS) − (beatOffsetMs × 1000)
     * </pre>
     *
     * This mirrors the exact line in {@code onTick()} and ensures the values
     * are correct for the two key cases: no offset and a 150 ms offset.
     */
    @Test
    public void testDriftCalculationWithOffset() {
        final int ticks = 16;

        // Case 1 — no beat offset
        // expected = 16 × 600 000 = 9 600 000 µs
        long expectedNoOffset = (ticks * TICK_DURATION_MICROS) - (0L * 1000L);
        assertEquals(9_600_000L, expectedNoOffset);

        // Case 2 — 150 ms beat offset
        // expected = 9 600 000 − 150 000 = 9 450 000 µs
        long expectedWithOffset = (ticks * TICK_DURATION_MICROS) - (150L * 1000L);
        assertEquals(9_450_000L, expectedWithOffset);
    }

    /**
     * Verify the two-phase interval selection logic:
     * ticks &lt; AGGRESSIVE_TICKS → interval = AGGRESSIVE_INTERVAL (2)
     * ticks ≥ AGGRESSIVE_TICKS → interval = NORMAL_INTERVAL (8)
     */
    @Test
    public void testDriftCorrectionIntervalSelection() {
        final int aggressiveTicks = 25;
        final int aggressiveInterval = 2;
        final int normalInterval = 8;

        // Inside aggressive window
        for (int t = 0; t < aggressiveTicks; t++) {
            int interval = (t < aggressiveTicks) ? aggressiveInterval : normalInterval;
            assertEquals("Ticks " + t + " should use aggressive interval", aggressiveInterval, interval);
        }

        // At and beyond the aggressive threshold
        for (int t = aggressiveTicks; t <= aggressiveTicks + 20; t++) {
            int interval = (t < aggressiveTicks) ? aggressiveInterval : normalInterval;
            assertEquals("Ticks " + t + " should use normal interval", normalInterval, interval);
        }
    }

    /**
     * The drift threshold is 20 ms (20 000 µs).  Verify that values just below
     * the threshold would not trigger a correction and values above would.
     */
    @Test
    public void testDriftThreshold() {
        final long threshold = 20_000L;

        assertFalse("19 ms drift should NOT trigger correction", Math.abs(19_000L) > threshold);
        assertFalse("20 ms drift is at threshold — should NOT trigger correction", Math.abs(20_000L) > threshold);
        assertTrue("21 ms drift SHOULD trigger correction", Math.abs(21_000L) > threshold);
        assertTrue("200 ms drift SHOULD trigger correction", Math.abs(200_000L) > threshold);
    }
}

package com.ticksync.music;

import java.io.File;
import java.util.Arrays;
import java.util.Comparator;
import javax.sound.midi.Instrument;
import javax.sound.midi.MidiSystem;
import javax.sound.midi.Patch;
import javax.sound.midi.Soundbank;
import javax.sound.midi.Synthesizer;

/**
 * Dumps every instrument in the OSRS soundfont (bank + program number + name),
 * then cross-references against the program numbers 556.mid actually requests.
 * This shows exactly which program numbers have matching instruments and which don't.
 */
public class SoundfontDiagnostic {
    // Program numbers that 556.mid requests (from MidiDiagnostic output)
    private static final int[][] MIDI_REQUESTS = {
        // {bank, program, channel}
        {0, 1, 0},
        {0, 19, 1},
        {0, 19, 2},
        {0, 45, 15},
        {0, 52, 3},
        {0, 44, 4},
        {0, 47, 5},
        {0, 46, 6},
        {1, 16, 7}, // only non-zero bank
        {0, 48, 8},
        {0, 48, 9},
        {0, 116, 11},
        {0, 61, 12},
        {0, 14, 10},
    };

    public static void main(String[] args) throws Exception {
        String sf2Path = "src/main/resources/soundfont/OSRS.sf2";
        if (args.length > 0) sf2Path = args[0];

        File f = new File(sf2Path);
        if (!f.exists()) {
            System.err.println("File not found: " + f.getAbsolutePath());
            return;
        }

        Synthesizer synth = MidiSystem.getSynthesizer();
        synth.open();

        Soundbank sb = MidiSystem.getSoundbank(f);
        Instrument[] instruments = sb.getInstruments();

        System.out.println("=== Soundfont: " + f.getName() + " ===");
        System.out.println("Total instruments: " + instruments.length);
        System.out.println();

        // Sort by bank then program for readability
        Arrays.sort(
                instruments,
                Comparator.comparingInt((Instrument i) -> i.getPatch().getBank())
                        .thenComparingInt(i -> i.getPatch().getProgram()));

        System.out.println("All instruments (bank, program, name):");
        System.out.println("----------------------------------------");
        for (Instrument inst : instruments) {
            Patch p = inst.getPatch();
            System.out.printf("  Bank %3d  Program %3d  %s%n", p.getBank(), p.getProgram(), inst.getName());
        }

        System.out.println();
        System.out.println("=== Cross-reference: 556.mid requests vs soundfont ===");
        System.out.println("ch  bank  prog  soundfont match");
        System.out.println("--  ----  ----  ---------------");
        for (int[] req : MIDI_REQUESTS) {
            int bank = req[0];
            int prog = req[1];
            int ch = req[2];

            // Java SF2 banks: the bank number in the Patch is bank*128 for MSB,
            // so bank 0 = 0, bank 1 = 128 in some implementations.
            // We check both raw and *128 variants.
            String match = findInstrument(instruments, bank, prog);
            String matchShifted = findInstrument(instruments, bank * 128, prog);

            if (!match.equals("(none)")) {
                System.out.printf("  ch%02d  %4d  %4d  ✓ %s%n", ch, bank, prog, match);
            } else if (!matchShifted.equals("(none)")) {
                System.out.printf("  ch%02d  %4d  %4d  ✓ (bank*128=%d) %s%n", ch, bank, prog, bank * 128, matchShifted);
            } else {
                System.out.printf("  ch%02d  %4d  %4d  ✗ NOT FOUND in soundfont%n", ch, bank, prog);
            }
        }

        synth.close();
        System.out.println();
        System.out.println("=== End Soundfont Diagnostic ===");
    }

    private static String findInstrument(Instrument[] instruments, int bank, int program) {
        for (Instrument inst : instruments) {
            if (inst.getPatch().getBank() == bank && inst.getPatch().getProgram() == program) {
                return inst.getName();
            }
        }
        return "(none)";
    }
}

package com.ticksync.music;

import static org.junit.Assert.*;

import javax.sound.midi.InvalidMidiDataException;
import javax.sound.midi.MetaMessage;
import javax.sound.midi.MidiEvent;
import javax.sound.midi.MidiMessage;
import javax.sound.midi.Sequence;
import javax.sound.midi.ShortMessage;
import javax.sound.midi.Track;
import org.junit.Test;

/**
 * Unit tests for {@link TempoQuantizer}.
 *
 * Covers:
 *  - quantize(float, SnapMode) for all three modes
 *  - process() rewriting SET_TEMPO events
 *  - process() handling multiple tempo changes in one sequence
 *  - remapDrumChannel moving ch9 events to ch15
 */
public class TempoQuantizerTest {
    // ── Shared helpers ────────────────────────────────────────────────────────

    /**
     * Build a minimal in-memory Sequence with a single SET_TEMPO meta-event
     * and a series of NOTE_ON events on the given channel.
     */
    static Sequence buildTestSequence(int bpm, int channel, int[] velocities) throws InvalidMidiDataException {
        Sequence seq = new Sequence(Sequence.PPQ, 480);
        Track track = seq.createTrack();

        addTempoEvent(track, bpm, 0);

        for (int i = 0; i < velocities.length; i++) {
            ShortMessage noteOn = new ShortMessage(ShortMessage.NOTE_ON, channel, 60, velocities[i]);
            track.add(new MidiEvent(noteOn, (long) i * 480));
        }
        return seq;
    }

    /** Add a SET_TEMPO meta-event to a track at the given tick. */
    private static void addTempoEvent(Track track, int bpm, long tick) throws InvalidMidiDataException {
        int micros = 60_000_000 / bpm;
        byte[] data = {(byte) ((micros >> 16) & 0xFF), (byte) ((micros >> 8) & 0xFF), (byte) (micros & 0xFF)};
        MetaMessage msg = new MetaMessage();
        msg.setMessage(0x51, data, 3);
        track.add(new MidiEvent(msg, tick));
    }

    // ── quantize(float, SnapMode) — NEAREST ──────────────────────────────────

    @Test
    public void testQuantizeNearest() {
        assertEquals(100f, TempoQuantizer.quantize(90f, SnapMode.NEAREST), 0.001f);
        assertEquals(50f, TempoQuantizer.quantize(60f, SnapMode.NEAREST), 0.001f);
        assertEquals(100f, TempoQuantizer.quantize(110f, SnapMode.NEAREST), 0.001f);
        // 140 is 40 from 100 and 60 from 200 → nearest is 100
        assertEquals(100f, TempoQuantizer.quantize(140f, SnapMode.NEAREST), 0.001f);
        assertEquals(200f, TempoQuantizer.quantize(160f, SnapMode.NEAREST), 0.001f);
        assertEquals(25f, TempoQuantizer.quantize(30f, SnapMode.NEAREST), 0.001f);
    }

    // ── quantize(float, SnapMode) — UP ───────────────────────────────────────

    @Test
    public void testQuantizeUp() {
        assertEquals(100f, TempoQuantizer.quantize(90f, SnapMode.UP), 0.001f);
        assertEquals(100f, TempoQuantizer.quantize(60f, SnapMode.UP), 0.001f);
        assertEquals(200f, TempoQuantizer.quantize(110f, SnapMode.UP), 0.001f);
        assertEquals(100f, TempoQuantizer.quantize(51f, SnapMode.UP), 0.001f);
        // 201 exceeds the highest valid BPM — clamp to 200
        assertEquals(200f, TempoQuantizer.quantize(201f, SnapMode.UP), 0.001f);
    }

    // ── quantize(float, SnapMode) — PREFER_UP ────────────────────────────────

    @Test
    public void testQuantizePreferUp() {
        // nearest=100 is above source (90) → keep 100
        assertEquals(100f, TempoQuantizer.quantize(90f, SnapMode.PREFER_UP), 0.001f);
        // nearest=50 is 17% below source (60) → exceeds 15% threshold → snap up to 100
        assertEquals(100f, TempoQuantizer.quantize(60f, SnapMode.PREFER_UP), 0.001f);
        // nearest=50 is above source (45) → keep 50
        assertEquals(50f, TempoQuantizer.quantize(45f, SnapMode.PREFER_UP), 0.001f);
        // nearest=100 is 9% below source (110) → within 15% → keep 100
        assertEquals(100f, TempoQuantizer.quantize(110f, SnapMode.PREFER_UP), 0.001f);
        // nearest=100 is 23% below source (130) → exceeds 15% → snap up to 200
        assertEquals(200f, TempoQuantizer.quantize(130f, SnapMode.PREFER_UP), 0.001f);
    }

    // ── process() — single tempo event ───────────────────────────────────────

    @Test
    public void testProcessRewritesTempoEvents() throws Exception {
        Sequence input = buildTestSequence(90, 0, new int[] {80, 80, 80});
        // remapChannel9=false — we're testing tempo only
        Sequence output = TempoQuantizer.process(input, SnapMode.NEAREST, false);

        float bpm = TempoQuantizer.getFirstTempoBPM(output);
        assertEquals("90 BPM should snap to 100 BPM", 100f, bpm, 0.001f);
    }

    // ── process() — multiple tempo changes ───────────────────────────────────

    @Test
    public void testProcessHandlesMultipleTempoChanges() throws Exception {
        Sequence seq = new Sequence(Sequence.PPQ, 480);
        Track track = seq.createTrack();

        // 90 → 100,  130 → 100 (nearest),  90 → 100
        addTempoEvent(track, 90, 0);
        addTempoEvent(track, 130, 480);
        addTempoEvent(track, 90, 960);

        Sequence output = TempoQuantizer.process(seq, SnapMode.NEAREST, false);

        int tempoCount = 0;
        for (Track t : output.getTracks()) {
            for (int i = 0; i < t.size(); i++) {
                MidiMessage msg = t.get(i).getMessage();
                if (msg instanceof MetaMessage) {
                    MetaMessage meta = (MetaMessage) msg;
                    if (meta.getType() == 0x51) {
                        byte[] data = meta.getData();
                        int micros = ((data[0] & 0xFF) << 16) | ((data[1] & 0xFF) << 8) | (data[2] & 0xFF);
                        float bpm = 60_000_000f / micros;
                        assertEquals("Every tempo event should snap to 100 BPM", 100f, bpm, 0.5f);
                        tempoCount++;
                    }
                }
            }
        }
        assertEquals("Expected exactly 3 tempo events", 3, tempoCount);
    }

    // ── process() — channel 9 remap ──────────────────────────────────────────

    @Test
    public void testChannelRemapMovesChannel9To15() throws Exception {
        Sequence seq = new Sequence(Sequence.PPQ, 480);
        Track track = seq.createTrack();

        // NOTE_ON and NOTE_OFF both on channel 9
        track.add(new MidiEvent(new ShortMessage(ShortMessage.NOTE_ON, 9, 60, 100), 0));
        track.add(new MidiEvent(new ShortMessage(ShortMessage.NOTE_OFF, 9, 60, 0), 480));

        // process with remapChannel9=true
        Sequence output = TempoQuantizer.process(seq, SnapMode.NEAREST, true);

        boolean foundCh9 = false;
        boolean foundCh15NoteOn = false;

        for (Track t : output.getTracks()) {
            for (int i = 0; i < t.size(); i++) {
                MidiMessage msg = t.get(i).getMessage();
                if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;
                    if (sm.getChannel() == 9) {
                        foundCh9 = true;
                    }
                    if (sm.getChannel() == 15
                            && sm.getCommand() == ShortMessage.NOTE_ON
                            && sm.getData1() == 60
                            && sm.getData2() == 100) {
                        foundCh15NoteOn = true;
                    }
                }
            }
        }

        assertFalse("No events should remain on channel 9 after remap", foundCh9);
        assertTrue("Channel 15 should contain the remapped NOTE_ON with correct note/velocity", foundCh15NoteOn);
    }
}

