package com.ticksync.music;

import static org.junit.Assert.*;

import org.junit.BeforeClass;
import org.junit.Test;

/**
 * Unit tests for {@link TrackDetector}.
 *
 * These tests exercise the mapping-load and name-validation logic only.
 * Track-detection (widget polling) is not tested here because it requires
 * a live RuneLite {@code Client}.
 *
 * A {@code null} client is passed to the constructor because the Client
 * reference is only used inside {@code checkForTrackChange()} — never
 * during mapping load or filename lookup.
 */
public class TrackDetectorTest {
    // Constructed once — construction triggers trackMappings.json load
    private static TrackDetector detector;

    @BeforeClass
    public static void setUp() {
        // null client is safe: Client is only accessed in checkForTrackChange()
        detector = new TrackDetector(null);
    }

    // ── trackMappings.json loading ────────────────────────────────────────────

    /**
     * Verify that the mapping file loads successfully and contains well-known
     * track-to-file entries.  Values are stored as "NNN.mid".
     */
    @Test
    public void testLoadTrackMappings() {
        assertEquals("556.mid", detector.getMidiFilename("Welcome to the Theatre"));
        assertEquals("495.mid", detector.getMidiFilename("The Desolate Mage"));
        assertNull("Unknown track should return null", detector.getMidiFilename("nonexistent track"));
    }

    /**
     * Spot-check a sample of entries that cover different parts of the alphabet,
     * confirming the full file was parsed rather than just the first few lines.
     */
    @Test
    public void testMappingContainsBroadRange() {
        // First entry alphabetically
        assertNotNull(detector.getMidiFilename("7th Realm"));
        // Mid-alphabet
        assertNotNull(detector.getMidiFilename("The Desolate Mage"));
        // Near end of file
        assertNotNull(detector.getMidiFilename("Welcome to the Theatre"));
    }

    // ── invalid track name detection ──────────────────────────────────────────

    /**
     * "Playing:", "Playing", empty string, and "-" are static UI labels that
     * appear in the widget before a real track name has loaded.
     * They must all be rejected.  A real track name ("Forever") must be accepted.
     */
    @Test
    public void testInvalidTrackNamesRejected() {
        assertTrue(TrackDetector.isInvalidTrackName("Playing:"));
        assertTrue(TrackDetector.isInvalidTrackName("Playing"));
        assertTrue(TrackDetector.isInvalidTrackName(""));
        assertTrue(TrackDetector.isInvalidTrackName("-"));
        assertTrue(TrackDetector.isInvalidTrackName(null));

        assertFalse(TrackDetector.isInvalidTrackName("Forever"));
    }

    /**
     * A mapped track name is not an invalid name, even if it happens to look short.
     */
    @Test
    public void testValidTrackNamesAccepted() {
        assertFalse(TrackDetector.isInvalidTrackName("7th Realm"));
        assertFalse(TrackDetector.isInvalidTrackName("Welcome to the Theatre"));
        assertFalse(TrackDetector.isInvalidTrackName("The Desolate Mage"));
    }
}

package com.ticksync.music;

import static org.junit.Assert.*;

import javax.sound.midi.InvalidMidiDataException;
import javax.sound.midi.MidiEvent;
import javax.sound.midi.MidiMessage;
import javax.sound.midi.Sequence;
import javax.sound.midi.ShortMessage;
import javax.sound.midi.Track;
import org.junit.Test;

/**
 * Unit tests for {@link VelocityNormalizer}.
 *
 * Covers:
 *  - normalize() scaling velocities to a target average
 *  - normalize() clamping scaled results to the [1, 127] range
 *  - normalize() leaving velocity-0 NOTE_ON events (note-off aliases) untouched
 *  - compress() reducing the dynamic range of a sequence
 */
public class VelocityNormalizerTest {
    // ── Shared helper ─────────────────────────────────────────────────────────

    /**
     * Build a minimal in-memory Sequence whose single track contains NOTE_ON
     * events at the supplied velocities, all on the given channel.
     */
    static Sequence buildTestSequence(int channel, int[] velocities) throws InvalidMidiDataException {
        Sequence seq = new Sequence(Sequence.PPQ, 480);
        Track track = seq.createTrack();

        for (int i = 0; i < velocities.length; i++) {
            ShortMessage msg = new ShortMessage(ShortMessage.NOTE_ON, channel, 60 + i, velocities[i]);
            track.add(new MidiEvent(msg, (long) i * 480));
        }
        return seq;
    }

    // ── normalize() ───────────────────────────────────────────────────────────

    /**
     * Scaling three notes with average velocity 60 to target 80 should produce
     * a new average of exactly 80.
     *
     * Scale = 80/60 = 1.333…
     * 30 × 1.333 = 40,  60 × 1.333 = 80,  90 × 1.333 = 120  → avg = 80.0
     */
    @Test
    public void testNormalizeScalesVelocity() throws Exception {
        // avg velocity = (30+60+90)/3 = 60
        Sequence input = buildTestSequence(0, new int[] {30, 60, 90});
        Sequence output = VelocityNormalizer.normalize(input, 80);

        long sum = 0;
        int count = 0;
        for (Track t : output.getTracks()) {
            for (int i = 0; i < t.size(); i++) {
                MidiMessage msg = t.get(i).getMessage();
                if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;
                    if (sm.getCommand() == ShortMessage.NOTE_ON && sm.getData2() > 0) {
                        sum += sm.getData2();
                        count++;
                    }
                }
            }
        }

        assertTrue("Expected at least 3 scaled notes", count >= 3);
        double newAvg = (double) sum / count;
        // Allow ±2 for integer rounding
        assertEquals("Normalized average should be ~80", 80.0, newAvg, 2.0);
    }

    /**
     * When the scale factor would push a velocity above 127, the result must
     * be clamped to 127.
     *
     * Scale = 127/120 ≈ 1.058  →  120 × 1.058 = 127.0  → clamped to 127.
     */
    @Test
    public void testNormalizeClampsTo127() throws Exception {
        Sequence input = buildTestSequence(0, new int[] {120});
        Sequence output = VelocityNormalizer.normalize(input, 127);

        for (Track t : output.getTracks()) {
            for (int i = 0; i < t.size(); i++) {
                MidiMessage msg = t.get(i).getMessage();
                if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;
                    if (sm.getCommand() == ShortMessage.NOTE_ON && sm.getData2() > 0) {
                        assertTrue("Scaled velocity must not exceed 127", sm.getData2() <= 127);
                    }
                }
            }
        }
    }

    /**
     * A NOTE_ON with velocity 0 is a note-off alias and must pass through
     * normalize() completely unchanged, regardless of the scale factor.
     *
     * When only velocity-0 events are present, normalize() returns the original
     * sequence unchanged (noteCount == 0 guard).
     */
    @Test
    public void testNormalizeSkipsVelocityZero() throws Exception {
        Sequence seq = new Sequence(Sequence.PPQ, 480);
        Track track = seq.createTrack();
        // velocity 0 → note-off alias
        ShortMessage noteOff = new ShortMessage(ShortMessage.NOTE_ON, 0, 60, 0);
        track.add(new MidiEvent(noteOff, 480));

        Sequence output = VelocityNormalizer.normalize(seq, 80);

        for (Track t : output.getTracks()) {
            for (int i = 0; i < t.size(); i++) {
                MidiMessage msg = t.get(i).getMessage();
                if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;
                    if (sm.getCommand() == ShortMessage.NOTE_ON) {
                        assertEquals("Velocity-0 NOTE_ON must be unchanged", 0, sm.getData2());
                    }
                }
            }
        }
    }

    // ── compress() ────────────────────────────────────────────────────────────

    /**
     * compress(ratio=3.0, threshold=90) applied to velocities [20, 40, 80, 120]:
     *   20 < FLOOR(30)  → boost: 20 + (30-20)×0.5 = 25   (louder, > 20)
     *   40              → no change (40 > floor, 40 < threshold)
     *   80              → no change (80 > floor, 80 < threshold)
     *   120 > 90        → compress: 90 + (120-90)/3 = 100 (quieter, < 120)
     */
    @Test
    public void testCompressReducesDynamicRange() throws Exception {
        Sequence input = buildTestSequence(0, new int[] {20, 40, 80, 120});
        Sequence output = VelocityNormalizer.compress(input, 3.0f, 90);

        int minVelocity = Integer.MAX_VALUE;
        int maxVelocity = Integer.MIN_VALUE;

        for (Track t : output.getTracks()) {
            for (int i = 0; i < t.size(); i++) {
                MidiMessage msg = t.get(i).getMessage();
                if (msg instanceof ShortMessage) {
                    ShortMessage sm = (ShortMessage) msg;
                    if (sm.getCommand() == ShortMessage.NOTE_ON && sm.getData2() > 0) {
                        int v = sm.getData2();
                        if (v < minVelocity) minVelocity = v;
                        if (v > maxVelocity) maxVelocity = v;
                    }
                }
            }
        }

        assertTrue("Loud notes should be tamed (max < 120)", maxVelocity < 120);
        assertTrue("Quiet notes should be boosted (min > 20)", minVelocity > 20);
    }
}
